// ── RETIRED surface — infix and/or connectives ────────────────────────────────

fn test_predicate_expr_parse_infix_and_retired() {
	// Infix `and` between operands is retired — only the prefix form
	// `and [P] [Q]` is canonical.
	assert_retired_predicate_body('@active and @verified')
}

fn test_predicate_expr_parse_infix_or_retired() {
	assert_retired_predicate_body('@a or @b')
}

fn test_predicate_expr_parse_infix_and_between_compares_retired() {
	assert_retired_predicate_body('@a=1 and @b=2')
}

fn test_predicate_expr_parse_unknown_paren_call_retired() {
	assert_retired_predicate_body('lower-case(@name)')
}

// ── Non-template general bodies error PREDICATE_EXPR_PARSE (fallback path) ────

fn test_predicate_expr_parse_fused_call_body_falls_out_of_templates() {
	// `$myfn $_` is a valid FUSED predicate at the program surface, but it
	// is not an atomic template — predicate_expr_parse must error with a
	// PREDICATE_EXPR_PARSE (not RETIRED) message so the caller keeps the
	// source-only fallback.
	_ := cx.predicate_expr_parse('\$myfn \$_') or {
		assert err.msg().starts_with('PREDICATE_EXPR_PARSE'), 'expected PREDICATE_EXPR_PARSE fallback error, got: ${err.msg()}'
		return
	}
	assert false, 'fused-call body should be outside the atomic templates'
}

fn test_predicate_expr_parse_empty_body_rejected() {
	_ := cx.predicate_expr_parse('') or { return }
	assert false, 'empty body should error'
}

fn test_predicate_expr_parse_garbage_rejected() {
	_ := cx.predicate_expr_parse('@@@') or { return }
	assert false, 'garbage body should error'
}

// ── Round-trip via parse_path: PathPredicate carries both source + expr ───────

fn test_parse_path_predicate_carries_structural_expr() {
	p := cx.parse_path('//user[@active]') or {
		assert false, 'parse failed: ${err}'
		return
	}
	assert p.steps.len == 1
	assert p.steps[0].predicates.len == 1
	pred := p.steps[0].predicates[0]
	// Source is preserved verbatim.
	assert pred.source == '@active'
	// Expr is promoted to a structural attr_test.
	if expr := pred.expr {
		assert expr.kind == cx.PredicateExprKind.attr_test
		if n := expr.name { assert n == 'active' } else { assert false, 'expr.name should be set' }
	} else {
		assert false, 'expr should have been promoted to structural AST'
	}
}

fn test_parse_path_predicate_attr_compare_round_trip() {
	p := cx.parse_path('//user[= \$_@name "alice"]') or {
		assert false, 'parse failed: ${err}'
		return
	}
	pred := p.steps[0].predicates[0]
	assert pred.source == '= \$_@name "alice"'
	if expr := pred.expr {
		assert expr.kind == cx.PredicateExprKind.attr_compare
		if n := expr.name { assert n == 'name' } else { assert false }
		if o := expr.op { assert o == '=' } else { assert false }
		if v := expr.value { assert v == '"alice"' } else { assert false }
	} else {
		assert false, 'expr should have been promoted'
	}
}

fn test_parse_path_infix_attr_compare_retired() {
	_ := cx.parse_path('//user[@name="alice"]') or {
		assert err.msg().starts_with('CXPATH_PARSE:'), 'expected CXPATH_PARSE error, got: ${err.msg()}'
		assert err.msg().contains('retired'), 'expected retired-surface message, got: ${err.msg()}'
		return
	}
	assert false, 'infix attribute comparison should be a hard parse error via parse_path'
}

fn test_parse_path_predicate_int_position_round_trip() {
	p := cx.parse_path('//user[3]') or {
		assert false, 'parse failed: ${err}'
		return
	}
	pred := p.steps[0].predicates[0]
	assert pred.source == '3'
	if expr := pred.expr {
		assert expr.kind == cx.PredicateExprKind.int_position
		if pos := expr.position { assert pos == 3 } else { assert false }
	} else {
		assert false, 'expr should have been promoted'
	}
}

fn test_parse_path_predicate_count_paren_retired() {
	_ := cx.parse_path('//user[count(*) > 5]') or {
		assert err.msg().starts_with('CXPATH_PARSE:'), 'expected CXPATH_PARSE error, got: ${err.msg()}'
		assert err.msg().contains('retired'), 'expected retired-surface message, got: ${err.msg()}'
		return
	}
	assert false, 'paren-call count(*) should be a hard parse error via parse_path'
}

fn test_parse_path_predicate_prefix_connective_round_trip() {
	p := cx.parse_path('//user[and [@active] [@verified]]') or {
		assert false, 'parse failed: ${err}'
		return
	}
	pred := p.steps[0].predicates[0]
	assert pred.source == 'and [@active] [@verified]'
	if expr := pred.expr {
		assert expr.kind == cx.PredicateExprKind.bool_expr
		if o := expr.op { assert o == 'and' } else { assert false }
		assert expr.children.len == 2
	} else {
		assert false, 'expr should have been promoted'
	}
}

// ── Round-trip via parse_path: retired infix + general-body fallback ──────────

fn test_parse_path_predicate_infix_and_retired() {
	// Infix `and` between operands is retired — a HARD parse error, never
	// a source-only fallback.
	_ := cx.parse_path('//user[@active and @verified]') or {
		assert err.msg().starts_with('CXPATH_PARSE:'), 'expected CXPATH_PARSE error, got: ${err.msg()}'
		assert err.msg().contains('retired'), 'expected retired-surface message, got: ${err.msg()}'
		return
	}
	assert false, 'infix `and` should be a hard parse error via parse_path'
}

fn test_parse_path_predicate_general_body_falls_back_to_source_only() {
	// `= $_position $_last` (the canonical replacement for last()) exceeds
	// the atomic templates — the parser MUST still produce a valid PathNode
	// with PathPredicate.source populated and .expr = none (the program
	// engine owns its structure).
	p := cx.parse_path('//user[= \$_position \$_last]') or {
		assert false, 'parse failed (should fall back gracefully): ${err}'
		return
	}
	assert p.steps.len == 1
	assert p.steps[0].predicates.len == 1
	pred := p.steps[0].predicates[0]
	assert pred.source == '= \$_position \$_last'
	assert pred.expr == none, 'expr should be none for a general body'
}

fn test_parse_path_predicate_fused_call_falls_back_to_source_only() {
	// A fused call predicate `[$myfn $_]` is valid surface; the path parser
	// keeps it source-only.
	p := cx.parse_path('//user[\$myfn \$_]') or {
		assert false, 'parse failed (should fall back gracefully): ${err}'
		return
	}
	pred := p.steps[0].predicates[0]
	assert pred.source == '\$myfn \$_'
	assert pred.expr == none, 'expr should be none for a fused call body'
}

// ── Equality interplay with PathPredicate ─────────────────────────────────────

fn test_path_predicate_eq_via_expr_ignores_source_formatting() {
	// Two paths with surface-formatting differences should compare
	// equal at the AST level when both predicates promote to the
	// same PredicateExpr structurally.
	p1 := cx.parse_path('//user[= \$_@active true]') or {
		assert false, 'parse failed: ${err}'
		return
	}
	p2 := cx.parse_path('//user[=  \$_@active   true]') or {
		assert false, 'parse failed: ${err}'
		return
	}
	assert p1.eq(p2), 'whitespace-differing predicates should compare equal via expr'
}

fn test_path_predicate_eq_falls_back_to_source_when_no_expr() {
	// Hand-construct two source-only PathPredicates (no expr). Source
	// match → equal; source diverge → unequal.
	a := cx.PathNode{
		form: cx.PathForm.descendant
		steps: [cx.PathStep{
			axis: cx.PathAxis.child
			node_test: 'user'
			predicates: [cx.PathPredicate{ source: 'foo and bar' }]
		}]
	}
	b := cx.PathNode{
		form: cx.PathForm.descendant
		steps: [cx.PathStep{
			axis: cx.PathAxis.child
			node_test: 'user'
			predicates: [cx.PathPredicate{ source: 'foo and bar' }]
		}]
	}
	assert a.eq(b)
	c := cx.PathNode{
		form: cx.PathForm.descendant
		steps: [cx.PathStep{
			axis: cx.PathAxis.child
			node_test: 'user'
			predicates: [cx.PathPredicate{ source: 'foo or baz' }]
		}]
	}
	assert !a.eq(c)
}

// ── source: vcx/tests/eval_budget_test.v ──
// eval_budget_test.v — the F4 evaluation budget (S6.2, RULED: F4, register
// 2026-08-08): every daemon-side pushdown evaluation runs under an
// operator-configured STEP LIMIT and MEMORY CEILING; exceeding either is the
// loud typed refusal `cx-err:CXER0273 E_EVAL_BUDGET_EXCEEDED` (core band
// 0270–0279 "host capability / runtime environment", the sibling of 0272
// E_STACK_EXHAUSTED), never a takedown. The profile listener translates the
// engine refusal to its wire row CXER5024 (xsp_store_profile.md §4.3).
//
// The budget is armed on the evaluation env (code.arm_eval_budget) and is
// SHARED through every same-thread env derivation — the closure-call path is
// exercised deliberately (the daemon's fold shape applies a def per entry).
// Once exceeded the refusal re-arms at every subsequent step, so a budgeted
// program cannot absorb it with [?fallback]-class handlers and continue —
// the budgeted evaluation is OVER (terminality lane below).
//
// Memory metering rides the MONOTONE allocated-bytes counter
// (gc_total_allocated — V fork; one atomic load under vgc, GC_get_total_bytes
// under Boehm), sampled every 64 steps: immune to collection dips, and a
// single monstrous allocation is still backstopped by the process arena
// ceiling (#277 loud OOM).

const eb_err = 'cx-err:CXER0273'

// eb_run parses + evaluates src under a budget (0 = that conjunct unbounded)
// and returns the rendered result text.
fn eb_run(src string, step_limit u64, mem_limit u64) string {
	prog := cx.parse_program(src) or { return 'PARSE_ERR ${err.msg()}' }
	mut env := code.new_env()
	if step_limit > 0 || mem_limit > 0 {
		b := code.arm_eval_budget(mut env, step_limit, mem_limit)
		assert b.step_limit == step_limit
		assert env.eval_budget != unsafe { nil }, 'arming must land on the env'
	}
	r := code.eval(prog.body, mut env) or { return 'EVAL_ERR ${err.msg()}' }
	return code.render_node_pub(r)
}

// A step-heavy pure program whose per-element body runs through a DEF CALL —
// pins budget propagation through the closure-call env derivation.
const eb_step_burner = '[?def bump ($x) [+ $x 1]]
[$count [?for [in $i [$range 1 1000000]] [yield [bump $i]]]]'

// An allocation-heavy program: ~200 MB of monotone allocation across ~50k
// iterations — trips a 16 MB ceiling deterministically long before completion.
const eb_mem_burner = "[?lib 'cx-stdlib/strings']
[$count [?for [in $i [$range 1 50000]] [yield [\$strings:repeat \"x\" 4000]]]]"

fn test_step_limit_refuses_typed() {
	out := eb_run(eb_step_burner, 50000, 0)
	assert out.contains(eb_err), 'step budget must refuse ${eb_err}, got: ${out}'
	assert out.contains('steps'), 'the refusal names its conjunct (steps): ${out}'
}

fn test_memory_ceiling_refuses_typed() {
	out := eb_run(eb_mem_burner, 0, u64(16) * 1024 * 1024)
	assert out.contains(eb_err), 'memory budget must refuse ${eb_err}, got: ${out}'
	assert out.contains('memory'), 'the refusal names its conjunct (memory): ${out}'
}

fn test_unbudgeted_eval_unaffected() {
	out := eb_run('[?def bump ($x) [+ $x 1]]
[$count [?for [in $i [$range 1 1000]] [yield [bump $i]]]]',
		0, 0)
	assert out == '1000', 'unbudgeted eval completes normally, got: ${out}'
}

fn test_generous_budget_unaffected() {
	out := eb_run('[?def bump ($x) [+ $x 1]]
[$count [?for [in $i [$range 1 1000]] [yield [bump $i]]]]',
		10000000, u64(1024) * 1024 * 1024)
	assert out == '1000', 'a generous budget must not perturb the result, got: ${out}'
}

fn test_budget_refusal_is_terminal_for_the_evaluation() {
	// A handler cannot absorb the refusal and continue: evaluating the
	// handler itself costs steps, and the exceeded budget re-refuses at
	// every step — the budgeted evaluation is over by construction.
	out := eb_run('[?def bump ($x) [+ $x 1]]
[?fallback [$count [?for [in $i [$range 1 1000000]] [yield [bump $i]]]] [recover-with "absorbed"]]',
		50000, 0)
	assert out.contains(eb_err), 'the refusal is terminal — a fallback handler must not convert it, got: ${out}'
	assert !out.contains('absorbed'), 'the handler value must never surface: ${out}'
}

fn test_memory_refusal_is_terminal_too() {
	// The latch lane the 64-step sampling makes load-bearing: without it a
	// memory-only budget would admit up to 63 handler steps between refusals.
	out := eb_run("[?lib 'cx-stdlib/strings']
[?fallback [$count [?for [in $i [$range 1 50000]] [yield [\$strings:repeat \"x\" 4000]]]] [recover-with \"absorbed\"]]",
		0, u64(16) * 1024 * 1024)
	assert out.contains(eb_err), 'the memory refusal is terminal, got: ${out}'
	assert !out.contains('absorbed'), 'the handler value must never surface: ${out}'
}

// ── source: vcx/tests/eval_data_fallback_test.v ──
// eval_data_fallback_test.v — #11: the eval/program reading must honour the
// spec invariant "a pure-data resource evaluates to itself" (code.md §1.3) even
// for prose/markup DATA documents whose element-body content the tokenized
// program reader cannot lex (em-dash, `;`, `,`, bullets, …) but the scannerless
// DATA reader accepts.
//
// Before the fix, `cx doc.cx` / `cx --json doc.cx` errored with CXER0100 on such
// documents (the data ⊂ program seam). The fix: when the program parse fails and
// there is no `$doc` input, fall back to the data reading via the SAME pipeline
// as `cx --from=cx --to=<target>` — so the eval output is byte-identical to the
// documented data path. A genuine program error that ALSO fails to parse as data
// still surfaces the original program error.

fn cx_bin() string {
	return testenv.cx_bin()
}

fn tmp_doc(label string, content string) string {
	path := os.join_path(os.temp_dir(), 'cx_dfb_${label}_${os.getpid()}.cx')
	os.write_file(path, content) or { panic(err) }
	return path
}

// Each case is a prose/markup data document that the program lexer/parser cannot
// read but the data reader accepts.
const prose_cases = [
	'[p hello — world]\n', // em-dash (non-ASCII byte 0xe2…)
	'[p one, two. three]\n', // comma + period punctuation
	'[p a; b]\n', // semicolon
	'[note • bullet item]\n', // bullet (non-ASCII)
	'[doc [title A — B] [body x; y, z.]]\n', // nested prose
]

// ── 1. eval default (cx) == data path (--from=cx --to=cx) ────────────────────

fn test_eval_default_matches_data_path_cx() {
	for i, src in prose_cases {
		f := tmp_doc('cx${i}', src)
		defer { os.rm(f) or {} }
		ev := os.execute('${cx_bin()} ${f}')
		dp := os.execute('${cx_bin()} --from=cx --to=cx ${f}')
		assert ev.exit_code == 0, 'case ${i}: eval errored: ${ev.output}'
		assert dp.exit_code == 0, 'case ${i}: data path errored: ${dp.output}'
		assert ev.output.trim_space() == dp.output.trim_space(),
			'case ${i}: eval(cx) != data path:\n  eval: ${ev.output}\n  data: ${dp.output}'
	}
}

// ── 2. eval --json == data path --to=json ────────────────────────────────────

fn test_eval_json_matches_data_path_json() {
	for i, src in prose_cases {
		f := tmp_doc('json${i}', src)
		defer { os.rm(f) or {} }
		ev := os.execute('${cx_bin()} --json ${f}')
		dp := os.execute('${cx_bin()} --from=cx --to=json ${f}')
		assert ev.exit_code == 0, 'case ${i}: eval --json errored: ${ev.output}'
		assert dp.exit_code == 0, 'case ${i}: data --to=json errored: ${dp.output}'
		assert ev.output.trim_space() == dp.output.trim_space(),
			'case ${i}: eval(json) != data path:\n  eval: ${ev.output}\n  data: ${dp.output}'
	}
}

// ── 3. The reported repro: em-dash in prose no longer errors ─────────────────

fn test_em_dash_prose_no_longer_errors() {
	f := tmp_doc('emdash', '[p hello — world]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} --json ${f}')
	assert r.exit_code == 0, 'em-dash prose still errors: ${r.output}'
	assert r.output.contains('hello — world'), 'content lost: ${r.output}'
}

// ── 4. A program that is valid PROGRAM still evaluates (no spurious fallback) ─

fn test_valid_program_still_evaluates() {
	f := tmp_doc('prog', '[+ 1 2]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code == 0, 'program errored: ${r.output}'
	assert r.output.trim_space() == '3', 'program did not evaluate (fallback fired wrongly?): ${r.output}'
}

// ── 5. A genuinely BROKEN resource (bad as program AND data) still errors ────

fn test_broken_resource_still_errors() {
	f := tmp_doc('broken', '[?def foo ($x)\n') // unterminated directive — bad both ways
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code != 0, 'broken resource should error, got: ${r.output}'
	assert r.output.contains('CXER0100'), 'expected a parse error, got: ${r.output}'
}

// ── 6. A lexable pure-data document still round-trips as identity via eval ───

fn test_lexable_data_identity_unaffected() {
	f := tmp_doc('cfg', '[config host=localhost]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code == 0, 'identity case errored: ${r.output}'
	assert r.output.trim_space() == '[config host=localhost]', 'identity broken: ${r.output}'
}

// ── 7. An UNKNOWN directive must STAY fail-loud, NOT fall back to data ───────
//
// Regression guard: the #11 data-fallback was gated too broadly (ANY program
// parse failure). An unknown `[?directive]` tokenizes fine and is REJECTED at
// the parse level (CXER0100), but it is ALSO a valid data element, so the
// fallback re-read it as data and silently round-tripped `[?nope]` instead of
// erroring. The fallback now fires only on a tokenizer (LexError) failure —
// real prose/markup — so a parse-level directive rejection surfaces the error.

fn test_unknown_directive_does_not_fall_back_to_data() {
	f := tmp_doc('unkdir', '[?this-directive-does-not-exist]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code != 0, 'unknown directive must error, not data-fall-back: ${r.output}'
	assert r.output.contains('CXER0100'), 'expected CXER0100, got: ${r.output}'
	assert r.output.contains('unknown directive'), 'expected the unknown-directive diagnostic, got: ${r.output}'
}

// ── 8. A RETIRED directive (`[?try]`, §2.5 tombstone) likewise stays an error ─

fn test_retired_try_directive_does_not_fall_back_to_data() {
	f := tmp_doc('rettry', '[?try [/ 10 0] [catch \$err 0]]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code != 0, 'retired [?try] must error, not data-fall-back: ${r.output}'
	assert r.output.contains('CXER0100'), 'expected CXER0100, got: ${r.output}'
}

// ── 9. #18: infix `=` inside [where] must FAIL LOUD with the prefix-form hint, ─
//        NOT silently data-fall-back to a data echo of the program source.
//
// `[?for … [where $x/@a=v] …]` is unambiguous PROGRAM intent — the parser
// committed to the `[where]` clause before hitting the infix `=`. Before the
// fix the program parse failed, the whole source re-read as a data element, and
// the helpful "use the prefix form" diagnostic (added on main, 4f17da73) was
// buried behind a data echo. The parser now flags this error program_committed
// so the eval boundary surfaces it instead of falling back.

fn test_where_infix_eq_fails_loud_not_data_fallback() {
	src := '[?let [= \$users [users [u active=true [email "a@x"]] [u active=false [email "b@x"]]]]\n' +
		'  [?for [in \$u \$users//u] [where \$u/@active=true] [yield \$u/email]]]\n'
	f := tmp_doc('whereinfix', src)
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code != 0, 'infix = in [where] must error, not data-fall-back: ${r.output}'
	assert r.output.contains('CXER0100'), 'expected CXER0100, got: ${r.output}'
	assert r.output.contains('PREFIX predicate'), 'expected the prefix-form hint, got: ${r.output}'
	// And it must NOT have silently echoed the source as data.
	assert !r.output.contains('[?for'), 'data-fallback fired (program echoed as data): ${r.output}'
}

// ── 10. A program-SHAPED resource (registered [?directive] in its data ────────
//        reading) whose program parse fails must FAIL LOUD, not echo as data.
//
// Field repro (xap-marine stage-2): a broken program — here a bare unquoted
// CXPath attr value inside [?for], which the program parser rejects — silently
// re-read as a DATA document and echoed itself back with exit 0. In a make
// target or CI that reads as success while the program never evaluated. The
// eval boundary now scans the data reading for registered program directives
// (string-aware: directives inside quoted prose are text) and surfaces the
// original program error for program-shaped sources.

fn test_program_shaped_lex_failure_fails_loud_not_data_echo() {
	src := '[?for \$f :in [\$doc select=//features/feature] :yield [out [\$f]]]\n'
	f := tmp_doc('progshape', src)
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code != 0, 'program-shaped source must error, not data-fall-back: ${r.output}'
	assert r.output.contains('CXER0100'), 'expected CXER0100, got: ${r.output}'
	assert !r.output.contains('[?for'), 'data-fallback fired (program echoed as data): ${r.output}'
}

// A TOKENIZER (LexError) failure inside a directive body — em-dash prose the
// program lexer cannot read — is the class the #11/#18 flags never see
// (tokenize() fails before the parser can set unknown_directive /
// program_committed). With a [?let] present the source is program-shaped, so
// it must error, not echo.

fn test_program_shaped_tokenizer_failure_fails_loud() {
	f := tmp_doc('progshapelex', '[?let [= \$x 1] [p a — b]]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code != 0, 'lexer breakage in a [?let] must error, not data-fall-back: ${r.output}'
	assert r.output.contains('CXER0100'), 'expected CXER0100, got: ${r.output}'
	assert !r.output.contains('[?let'), 'data-fallback fired (program echoed as data): ${r.output}'
}

// String-awareness guard: prose that MENTIONS a directive inside quoted text
// is NOT program-shaped — the quoted span parses as text content, not as a
// directive node — so the prose fallback still applies.

fn test_prose_mentioning_directive_in_quotes_still_falls_back() {
	f := tmp_doc('prosequote', '[note — "use [?let] for bindings"]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code == 0, 'quoted-directive prose must still fall back: ${r.output}'
	assert r.output.contains('use [?let] for bindings'), 'content lost: ${r.output}'
}

// The corrected PREFIX form still computes (no over-broad fail-loud regression).

fn test_where_prefix_form_still_computes() {
	src := '[?let [= \$users [users [u active=true [email "a@x"]] [u active=false [email "b@x"]] [u active=true [email "c@x"]]]]\n' +
		'  [?for [in \$u \$users//u] [where [= \$u/@active true]] [yield \$u/email]]]\n'
	f := tmp_doc('whereprefix', src)
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code == 0, 'prefix [where] errored: ${r.output}'
	assert r.output.contains('a@x') && r.output.contains('c@x'), 'prefix filter wrong: ${r.output}'
	assert !r.output.contains('b@x'), 'prefix filter did not exclude inactive: ${r.output}'
}

// ── #472: rooted-path glued `@attr` tail after a predicate fails LOUD ─────────
//
// `//team/member[= $_@name "alpha"]@id` in element-body position silently
// degraded to a text run: the glued `@` tail is not a rooted-PathExpr surface
// (grammar [130a] separates steps with '/'; canonical.md §2.12.6 — the glued
// `@attr` tail is BindingPath-only, [135a]/[162]), the unconsumed `@` failed the
// program parse with a generic error, and the eval boundary silently re-read the
// whole resource as DATA (rc=0, silent wrong answer). A fused [159b] predicate
// body is not prose: once a step carries a parsed predicate the parser has
// committed to a program construct, so the error is program_committed and the
// diagnostic (pointing at the `/@attr` spelling) must surface.

fn test_rooted_path_attr_tail_after_predicate_fails_loud() {
	src := '[teams\n' +
		'  [team name="alpha" [member id=1] [member id=2]]\n' +
		'  [team name="beta" [member id=3]]]\n' +
		'[r //team/member[= \$_@name "alpha"]@id]\n'
	f := tmp_doc('attrtailpred', src)
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code != 0, 'glued @attr tail after a predicate must error, not data-fall-back: ${r.output}'
	assert r.output.contains('CXER0100'), 'expected CXER0100, got: ${r.output}'
	assert r.output.contains('/@attr'), 'expected the /@attr rewrite hint, got: ${r.output}'
	// And it must NOT have silently echoed the path source as a text run.
	assert !r.output.contains("'//team/member"), 'data-fallback fired (path echoed as text): ${r.output}'
}

// The spelled `/@attr` step after a predicate computes (the grammar-conformant
// form of the same query — no over-broad fail-loud regression).

fn test_rooted_path_predicate_then_slash_attr_still_computes() {
	src := '[teams\n' +
		'  [team name="alpha" [member id=1] [member id=2]]\n' +
		'  [team name="beta" [member id=3]]]\n' +
		'[r [?splice //team/member[= \$_@id 1]/@id]]\n' // R-A1: the node-set splices into content
	f := tmp_doc('attrtailslash', src)
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code == 0, 'spelled /@attr after predicate errored: ${r.output}'
	assert r.output.contains('[id 1]'), 'expected the attribute node, got: ${r.output}'
}

// Binding-path glued tails (`$doc//team/member[pred]@id`) are grammar-
// sanctioned surface ([135a] BindingStep / [162] BindingPostfix) and keep
// working.

fn test_binding_path_glued_attr_tail_still_computes() {
	src := '[?let [= \$d [teams [team name="alpha" [member id=1] [member id=2]] [team name="beta" [member id=3]]]]\n' +
		' [r [?splice \$d//team/member[= \$_@id 1]@id]]]\n' // R-A1: the node-set splices into content
	f := tmp_doc('attrtailbind', src)
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code == 0, 'binding-path glued @attr tail errored: ${r.output}'
	assert r.output.contains('[id 1]'), 'expected the attribute node, got: ${r.output}'
}

// The bare (predicate-free) glued tail stays PROSE-ELIGIBLE: `//host/share@snap`
// -like spans are legitimate data text, so a document whose program reading
// trips only on a bare glued tail still falls back to the data reading. The
// decision boundary is the predicate: fused predicate = program intent (loud),
// bare tail = prose (data echo).

fn test_rooted_path_bare_attr_tail_prose_still_falls_back() {
	f := tmp_doc('attrtailprose', '[note see //docs/readme@main for details]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code == 0, 'bare glued-tail prose must still fall back: ${r.output}'
	assert r.output.contains('//docs/readme@main'), 'prose content lost: ${r.output}'
}

// ── #471: [?modify] focus predicate referencing a free/outer binding ──────────
//
// The standalone modify bridge's predicate filter evaluates against an empty
// env; a focus predicate referencing a binding beyond the reserved $_ /
// $_position / $_last set identity-passed EVERY candidate (both members
// flagged, rc=0). The bridge now declines such paths: a genuinely unbound
// binding surfaces CXER0001 via the legacy evaluator's full program-eval
// predicates; a bound outer binding filters correctly. (Conformance:
// program-modify-outer-pred-001…005 in conformance/code.cxd.)

fn test_modify_focus_predicate_unbound_binding_raises() {
	src := '[?let [= \$d [teams [team name="alpha" [member id=1]] [team name="beta" [member id=2]]]]\n' +
		' [?modify \$d //team/member[= \$qqq@name "alpha"] [set-attr flagged true]]]\n'
	f := tmp_doc('modunbound', src)
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code != 0, 'unbound \$qqq in modify focus predicate must raise, not identity-pass: ${r.output}'
	assert r.output.contains('CXER0001'), 'expected CXER0001, got: ${r.output}'
}

fn test_modify_focus_predicate_bound_outer_binding_filters() {
	src := '[?let [= \$d [teams [team name="alpha" [member id=1]] [team name="beta" [member id=2]]]]\n' +
		' [?let [= \$flag "alpha"]\n' +
		'  [?modify \$d //team[= \$_@name \$flag]/member [set-attr flagged true]]]]\n'
	f := tmp_doc('modbound', src)
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code == 0, 'bound outer binding in modify focus predicate errored: ${r.output}'
	assert r.output.contains('[team name=alpha [member id=1 flagged=true]]'), 'alpha member not flagged: ${r.output}'
	assert r.output.contains('[team name=beta [member id=2]]'), 'beta member wrongly flagged (identity-pass): ${r.output}'
}

// ── #421: the [?cx …] PI/config namespace is NOT a §4.1 directive ────────────
//
// Regression guard: the unknown-directive fail-loud classification (the class-1
// flag added for #11) treated EVERY registry miss as program intent — including
// the `cx` CXDirective namespace (grammar [34]; the [59a] note: the bare name
// `cx` is NOT an EvalName). That broke the approved code.md §13 include surface
// (`[?cx include=…]` — preserved verbatim when no include root is supplied) and
// every bare `[?cx …]` config PI, in .cx and .cxd alike. The fix classifies the
// `cx` head BEFORE the §4.1 registry lookup and parses the directive via the
// node_lit DATA↔PROGRAM seam, so the program reading of a CXDirective IS the
// data reading. Unknown `[?name]` heads other than `cx` stay fail-closed
// (tests 7/8 above pin that).

fn test_cx_include_directive_preserved_in_program_mode() {
	f := tmp_doc('cxinc', '[config [?cx include=defaults.cx] [a 1]]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code == 0, '[?cx include] must parse in program mode: ${r.output}'
	assert r.output.contains('[?cx include=defaults.cx]'),
		'include directive not preserved verbatim: ${r.output}'
	assert r.output.contains('[a 1]'), 'sibling content lost: ${r.output}'
}

fn test_bare_cx_config_pi_passes_through() {
	path := os.join_path(os.temp_dir(), 'cx_dfb_cxpi_${os.getpid()}.cxd')
	os.write_file(path, '[?cx version=1.0]\n[config [a 1]]\n') or { panic(err) }
	defer { os.rm(path) or {} }
	r := os.execute('${cx_bin()} ${path}')
	assert r.exit_code == 0, 'bare [?cx version=…] PI must not error: ${r.output}'
	assert r.output.contains('[?cx version=1.0]'), 'config PI not preserved: ${r.output}'
	assert r.output.contains('[a 1]'), 'document content lost: ${r.output}'
}

fn test_unknown_cx_key_refuses_closed() {
	// grammar [34]'s historical "open by design" clause is RETIRED (CXP-1,
	// 2026-08-20): the pragma key set is a closed registry (include | schema
	// | version | lint-disable | lint-enable), and an unknown key is a loud
	// typed parse refusal naming the registry — the silent-acceptance class
	// the language refuses everywhere else.
	f := tmp_doc('cxbogus', '[?cx bogus=1]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code != 0, 'unknown [?cx key must refuse (CXP-1): ${r.output}'
	assert r.output.contains('unknown [?cx] pragma key'), 'refusal must name the class: ${r.output}'
	assert r.output.contains('lint-enable'), 'refusal must name the registry: ${r.output}'
}

// ── source: vcx/tests/eval_stack_guard_test.v ──
// eval_stack_guard_test.v — deep NON-tail cx recursion must never SIGSEGV (#319).
//
// The failure this pins: the evaluator is a tree-walker and only TAIL calls
// are trampolined (#60), so every non-tail recursion level is a real C-stack
// cycle (eval_node → eval_cx_element → dispatch → run_closure_body →
// eval_tail; ~63 KB/level dev -O0, ~28 KB/level -Os). ~120 levels overflowed
// the default 8 MB stack and died by SIGSEGV — shallow for real programs
// (tree walks over deep docs). The #282 arena test only survived its 120
// non-tail levels by raising the stack rlimit first.
//
// The fix (cx_stack_guard.c + eval_stack_guard.c.v): a per-thread stack
// watermark probed at every eval_node entry. Under ~1 MiB of remaining
// headroom (size/4 on tiny stacks) eval returns the CATCHABLE value-form err
// `cx-err:CXER0272` (E_STACK_EXHAUSTED, spec/core/code.md §9.4/§9.5) instead
// of crashing. Watermark, not a depth counter: the per-level footprint varies
// ~8x between build modes, so only measuring the live stack pointer holds
// across all of them.
//
// Child-process shape (the vgc_oom_loud_test precedent): a SIGSEGV must be
// observable as the child's exit status, never kill the harness. In-process
// happy-path fixtures live in conformance/code.cxd (program-stack-guard-*).

const guard_depth = 1_000_000 // levels; unreachable on any plausible stack

fn cx_bin_guard() string {
	return testenv.cx_bin()
}

fn write_prog(name string, src string) string {
	prog := os.join_path(os.temp_dir(), '${name}_${os.getpid()}.cx')
	os.write_file(prog, src) or { panic(err) }
	return prog
}

// The canonical non-tail shape: the `[+ 1 …]` wrapper makes every recursive
// call non-tail, so each level holds a real C frame until unwind.
fn non_tail_def() string {
	return '[?def sum1 (\$n)\n' + '  [?if [= \$n 0]\n' + '    [then 0]\n' +
		'    [else [+ 1 [sum1 [- \$n 1]]]]]]\n'
}

fn run_child(prefix string, prog string) os.Result {
	return os.execute('${prefix}VNOBUGREPORT=1 ${cx_bin_guard()} ${prog} 2>&1')
}

fn test_deep_non_tail_raises_coded_err_never_segv() {
	prog := write_prog('stack_guard_deep', non_tail_def() + '[sum1 ${guard_depth}]\n')
	defer {
		os.rm(prog) or {}
	}
	res := run_child('', prog)
	// 139 = the shell reporting death by SIGSEGV — the exact pre-#319 shape.
	assert res.exit_code != 139, 'deep non-tail recursion still segfaults (pre-#319 shape):\n${res.output.limit(2000)}'
	assert res.output.contains('cx-err:CXER0272'), 'expected the E_STACK_EXHAUSTED err, got:\n${res.output.limit(2000)}'
}

fn test_deep_non_tail_is_recoverable_by_fallback() {
	// Errors are values (§9.1): CXER0272 railway-propagates and MUST be
	// catchable like any other err — the program recovers and exits clean.
	prog := write_prog('stack_guard_fallback', non_tail_def() +
		'[?fallback [sum1 ${guard_depth}] [recover-with "recovered"]]\n')
	defer {
		os.rm(prog) or {}
	}
	res := run_child('', prog)
	assert res.exit_code == 0, 'fallback-recovered run must exit 0:\n${res.output.limit(2000)}'
	assert res.output.contains('recovered'), 'expected the recover-with value, got:\n${res.output.limit(2000)}'
	assert !res.output.contains('CXER0272'), 'err leaked past [?fallback]:\n${res.output.limit(2000)}'
}

fn test_tail_call_at_same_depth_still_completes() {
	// TCO regression guard (#60): the SAME depth tail-recursively runs in
	// O(1) native stack — the guard must never fire on the trampoline.
	prog := write_prog('stack_guard_tail', '[?def loop (\$n \$acc)\n' +
		'  [?if [= \$n 0]\n' + '    [then \$acc]\n' +
		'    [else [loop [- \$n 1] [+ \$acc 1]]]]]\n' + '[loop ${guard_depth} 0]\n')
	defer {
		os.rm(prog) or {}
	}
	res := run_child('', prog)
	assert res.exit_code == 0, 'tail recursion at guard depth must complete:\n${res.output.limit(2000)}'
	assert res.output.contains('${guard_depth}'), 'wrong tail-loop result:\n${res.output.limit(2000)}'
}

fn test_worker_thread_deep_non_tail_never_crashes() {
	// [?worker] bodies run on their own V thread (8 MB default via V spawn,
	// NOT the main thread's rlimit) — the guard arms per thread, so the
	// worker's own bounds gate it. The stack err surfaces through the
	// §10.4.8 worker-panic wrap: CXER0220 with the CXER0272 cause inside.
	prog := write_prog('stack_guard_worker', non_tail_def() +
		'[?let [= \$w [?worker name="wdeep" [body [sum1 ${guard_depth}]]]] [?wait-for worker=\$w]]\n')
	defer {
		os.rm(prog) or {}
	}
	res := run_child('', prog)
	assert res.exit_code != 139, 'worker-thread deep recursion segfaulted:\n${res.output.limit(2000)}'
	assert res.output.contains('cx-err:CXER0272'), 'worker result must carry the E_STACK_EXHAUSTED cause:\n${res.output.limit(2000)}'
}

fn test_past_old_crash_depth_completes_or_raises_never_segv() {
	// The issue's contract at the old crash depth (~120 levels on 8 MB dev):
	// depth 200 either completes (small frames / big stack) or raises the
	// coded err (big frames / default stack) — NEVER a signal. Both outcomes
	// are legal; the crash is not.
	prog := write_prog('stack_guard_200', non_tail_def() + '[sum1 200]\n')
	defer {
		os.rm(prog) or {}
	}
	res := run_child('', prog)
	assert res.exit_code != 139, 'depth-200 non-tail recursion segfaulted (pre-#319 shape):\n${res.output.limit(2000)}'
	completed := res.output.trim_space() == '200'
	raised := res.output.contains('cx-err:CXER0272')
	assert completed || raised, 'depth 200 must complete or raise CXER0272, got:\n${res.output.limit(2000)}'
}

fn test_raised_rlimit_extends_depth() {
	// The guard measures the REAL stack (macOS main thread: exec-time
	// rlimit, not pthread's 8 MB default) — the #282 arena test depends on
	// exactly this: under `ulimit -s 65520` its 120 non-tail levels must
	// complete instead of tripping a guard pinned to the default size.
	prog := write_prog('stack_guard_rlimit', non_tail_def() + '[sum1 200]\n')
	defer {
		os.rm(prog) or {}
	}
	res := os.execute('ulimit -s unlimited 2>/dev/null || ulimit -s 65520 2>/dev/null; ' +
		'VNOBUGREPORT=1 exec ${cx_bin_guard()} ${prog} 2>&1')
	assert res.exit_code == 0, 'depth 200 under a raised stack rlimit must complete:\n${res.output.limit(2000)}'
	assert res.output.trim_space() == '200', 'wrong result under raised rlimit:\n${res.output.limit(2000)}'
}

fn test_tiny_stack_scaled_margin_keeps_shallow_eval_usable() {
	// Threads with < 4 MiB stacks get a proportional margin (size/4) instead
	// of the fixed 1 MiB — a 2 MB-ulimit run must still evaluate shallow
	// programs, and deep ones must raise the coded err, not crash.
	shallow := write_prog('stack_guard_tiny_ok', non_tail_def() + '[sum1 10]\n')
	deep := write_prog('stack_guard_tiny_deep', non_tail_def() + '[sum1 ${guard_depth}]\n')
	defer {
		os.rm(shallow) or {}
		os.rm(deep) or {}
	}
	res_ok := os.execute('ulimit -s 2048 2>/dev/null; VNOBUGREPORT=1 exec ${cx_bin_guard()} ${shallow} 2>&1')
	assert res_ok.exit_code == 0, 'shallow eval on a 2 MB stack must work:\n${res_ok.output.limit(2000)}'
	assert res_ok.output.trim_space() == '10', 'wrong shallow result on 2 MB stack:\n${res_ok.output.limit(2000)}'
	res_deep := os.execute('ulimit -s 2048 2>/dev/null; VNOBUGREPORT=1 exec ${cx_bin_guard()} ${deep} 2>&1')
	assert res_deep.exit_code != 139, 'deep recursion on a 2 MB stack segfaulted:\n${res_deep.output.limit(2000)}'
	assert res_deep.output.contains('cx-err:CXER0272'), 'expected E_STACK_EXHAUSTED on the 2 MB stack:\n${res_deep.output.limit(2000)}'
}

// ── source: vcx/tests/scoping_lexical_test.v ──
// RED → GREEN TDD for UNIFORM LEXICAL SCOPING (cx-private #19, #22;
// spec/03-approved/core/code.md). A callable must resolve its free
// names — sibling functions AND module values/consts — in its DEFINING
// environment, not the caller's. These fixtures FAIL on the pre-fix engine
// (closures alias the caller's closures table + snapshot bindings before consts
// load) and pass once the defining-scope model lands. Behavior, not names.

// Helper: run a program text in a fresh temp dir (for local [?lib] resolution),
// returning the rendered output. Restores cwd.
fn run_in_tmp(files map[string]string, main_src string) string {
	prev := os.getwd()
	dir := os.join_path(os.temp_dir(), 'cx-scope-${os.getpid()}-${files.len}-${main_src.len}')
	os.mkdir_all(dir) or { return 'MKDIR-FAIL: ${err}' }
	for name, body in files {
		os.write_file(os.join_path(dir, name), body) or { return 'WRITE-FAIL: ${err}' }
	}
	os.chdir(dir) or { return 'CHDIR-FAIL: ${err}' }
	out := code.eval_code('', main_src, 'text') or {
		os.chdir(prev) or {}
		return 'EVAL-ERR: ${err}'
	}
	os.chdir(prev) or {}
	os.rmdir_all(dir) or {}
	return out
}

// #22 — a [?const] referenced inside a [?def] body must dereference to its value
// (consistent with top-level + argument use). Pre-fix: the def captures bindings
// BEFORE the top-level two-pass evaluates consts, so the body sees `Q` as a
// bareword (count 1) instead of the 2-element sequence.
fn test_const_in_def_body() {
	prog := "[?const Q ([q sym=A], [q sym=B])]
[?def f-inside pure () [\$count Q]]
[?def f-arg pure (\$q) [\$count \$q]]
[probe top=[\$count Q] inside=[\$f-inside] viaarg=[\$f-arg Q]]"
	out := code.eval_code('', prog, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out.contains('inside=2'), 'const Q must deref inside a def body (expect inside=2), got: ${out}'
	assert out.contains('top=2'), 'sanity: top-level const deref, got: ${out}'
	assert out.contains('viaarg=2'), 'sanity: const-as-arg deref, got: ${out}'
}

// #19 — in a module loaded via [?lib], a [?def] must be able to call a SIBLING
// [?def] (resolved in the module's defining scope). Pre-fix: `[$l:b]` raises
// `no callable "a"` because the call env aliases the importer's closures, which
// lack the module's unqualified `a`.
fn test_lib_sibling_def_call() {
	out := run_in_tmp({
		'lib_c.cx': '[?def a scope=public pure () 41]\n[?def b scope=public pure () [+ [\$a] 1]]\n'
	}, "[?lib './lib_c.cx' :as l]\n[out [\$l:b]]")
	assert out.contains('42'), 'imported sibling-def call must work (expect 42), got: ${out}'
	assert !out.contains('no callable'), 'sibling a must resolve in the module scope, got: ${out}'
}

// Mutual recursion (letrec) across sibling defs in an imported module.
fn test_lib_mutual_recursion() {
	out := run_in_tmp({
		'lib_mr.cx': '[?def is-even scope=public pure (\$n) [?if [= \$n 0] [then true] [else [\$is-odd [- \$n 1]]]]]\n[?def is-odd scope=public pure (\$n) [?if [= \$n 0] [then false] [else [\$is-even [- \$n 1]]]]]\n'
	}, "[?lib './lib_mr.cx' :as m]\n[out [\$m:is-even 4]]")
	assert out.contains('true'), 'mutual recursion across sibling defs in a lib (is-even 4=true), got: ${out}'
	assert !out.contains('no callable'), 'mutual-recursive sibling must resolve, got: ${out}'
}

// 3-level transitive sibling calls in an imported module (a→b→c).
fn test_lib_transitive_three_level() {
	out := run_in_tmp({
		'lib_t.cx': '[?def c scope=public pure () 3]\n[?def b scope=public pure () [+ [\$c] 10]]\n[?def a scope=public pure () [+ [\$b] 100]]\n'
	}, "[?lib './lib_t.cx' :as t]\n[out [\$t:a]]")
	assert out.contains('113'), 'transitive sibling calls a->b->c (expect 113), got: ${out}'
	assert !out.contains('no callable'), 'transitive siblings must resolve, got: ${out}'
}

// A [?const] referenced inside a [?def] body, both in an imported module.
fn test_lib_const_in_def() {
	out := run_in_tmp({
		'lib_k.cx': "[?const BASE 100]\n[?def bumped scope=public pure () [+ BASE 5]]\n"
	}, "[?lib './lib_k.cx' :as k]\n[out [\$k:bumped]]")
	assert out.contains('105'), 'module const referenced in a sibling def body (expect 105), got: ${out}'
}

// #20 — a [?lib]/[?def]/[?const] directive inside a `#` comment line in an
// IMPORTED module must be ignored (as it is on a direct run), not scanned by the
// module loader's directive extraction (which would try to resolve the commented
// import and fail with MODULE_FILE_NOT_FOUND / a spurious cycle).
fn test_lib_commented_directive_ignored() {
	out := run_in_tmp({
		'lib_cmt.cx': "# [?lib './ghost.cx']\n[?def f scope=public pure () 7]\n"
	}, "[?lib './lib_cmt.cx' :as l]\n[out [\$l:f]]")
	assert out.contains('7'), 'a commented [?lib] in an imported module must be ignored (expect 7), got: ${out}'
	assert !out.contains('ghost'), 'the commented import must NOT be resolved, got: ${out}'
}

// ── source: vcx/tests/closure_escape_test.v ──
// closure_escape_test.v — BEHAVIORAL coverage for the closure-escape
// representation fix (cx-private #45). An ESCAPING closure ([?fn] returned from a
// def) carries its Closure ON its function-value sentinel, so it travels WITH the
// value and resolves against its own DEFINING scope wherever applied — no
// id→scope-table registry. This pins the cross-MODULE cases the single-program
// conformance harness (conformance/code.cxd, stdlib/run.cxd) cannot express:
// they need a real [?lib './m.cx'] boundary. The program-level Bug-1 (zero-arg
// def returns anon) + Bug-3 (nested pipe re-capture) are pinned in code.cxd
// (program-for-013b/013c) and stdlib/run.cxd (run-007).
//
// Bug-2: a returned anon from a MODULE def resolves its module's UNQUALIFIED
// siblings when applied from the caller's frame (not the caller's scope). Before
// the fix the anon resolved against the caller (or the program-scope mirror) and
// failed with `no callable "<sibling>"`.

fn cx_binary() string {
	return testenv.cx_bin()
}

// run_program writes the given module + entry sources into a fresh temp dir
// (so `[?lib './m.cx']` resolves relative to the entry file) and runs the entry
// through the real cx binary, returning trimmed stdout+stderr.
fn run_program(files map[string]string, entry string) string {
	dir := os.join_path(os.temp_dir(), 'cx45_${os.getpid()}_${entry.all_before('.')}')
	os.mkdir_all(dir) or { panic('mkdir ${dir}: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	for name, content in files {
		os.write_file(os.join_path(dir, name), content) or { panic('write ${name}: ${err}') }
	}
	// Run from inside the temp dir so a `[?lib './m.cx']` resolves relative to it
	// (the resolver is process-CWD relative).
	res := os.execute('cd ${dir} && ${cx_binary()} ${entry}')
	return res.output.trim_space()
}

// Bug-2 — a returned anon from a ≥1-arg MODULE def calls an UNQUALIFIED sibling
// (`helper`) of its own module. Resolves against the module, not the caller.
fn test_returned_anon_resolves_module_sibling() {
	mod := "[?def helper scope=public (\$x) [+ \$x 1]]\n" +
		"[?def mk scope=public (\$u) [?fn (\$p) [\$helper \$p]]]\n"
	main := "[?lib './m.cx' :as m]\n[?let [= \$f [\$m:mk 99]] [\$f 10]]\n"
	got := run_program({ 'm.cx': mod, 'main.cx': main }, 'main.cx')
	assert got == '11', 'module-sibling-resolving returned anon: expected 11, got `${got}`'
}

// Bug-2 (zero-arg variant) — a returned anon from a ZERO-arg MODULE def likewise
// resolves its module sibling. The zero-arg def is invoked with the call sigil
// [$m:mk] (a bare 0-arg head is a data element, not a call).
fn test_returned_anon_zero_arg_module_def() {
	mod := "[?def helper scope=public (\$x) [* \$x 2]]\n" +
		"[?def mk scope=public () [?fn (\$p) [\$helper \$p]]]\n"
	main := "[?lib './m.cx' :as m]\n[?let [= \$f [\$m:mk]] [\$f 21]]\n"
	got := run_program({ 'm.cx': mod, 'main.cx': main }, 'main.cx')
	assert got == '42', 'zero-arg module def returned anon: expected 42, got `${got}`'
}

// Variant C — a captured let-BINDING survives when the closure is applied from
// another module (here via cx-x/run's invoke). The returned anon closes over a
// module const ($base) AND its param ($m); both must be live at apply time.
fn test_captured_binding_survives_cross_module_apply() {
	mod := "[?const scope=public base 100]\n" +
		"[?def mk scope=public (\$m) [?fn (\$p) [+ [+ \$base \$m] \$p]]]\n"
	main := "[?lib 'cx-x/run' :as run]\n[?lib './m.cx' :as m]\n" +
		"[?let [= \$f [\$m:mk 20]] [\$run:invoke \$f 3]]\n"
	got := run_program({ 'm.cx': mod, 'main.cx': main }, 'main.cx')
	assert got == '123', 'captured const+param across module apply: expected 123, got `${got}`'
}

// ── source: vcx/tests/recursive_def_dispatch_test.v ──
// recursive_def_dispatch_test.v — #53: a self-recursive (or mutually
// recursive) [?def] called by its BAREWORD head — `[loop …]`, not `[$loop …]` —
// must dispatch as a call, not fall through to data-element construction.
//
// Root cause: the element-form closure dispatch (eval_cx_element) gated the
// multi-arg whitespace call on `all_items_are_expr_position`, which rejected an
// argument that is itself an OPERATOR-headed element (`[- $n 1]`). So a recursive
// call doing arithmetic on its counter — `[loop [- $n 1] …]` — was built as the
// data element `[loop 1 'x']` instead of recursing. The corrupted (un-evaluated)
// result then made the caller's downstream stdlib call read as "no callable".

fn run_src(src string) os.Result {
	f := os.join_path(os.temp_dir(), 'cx_rec_${os.getpid()}_${src.len}.cx')
	os.write_file(f, src) or { panic(err) }
	defer { os.rm(f) or {} }
	return os.execute('${cx_bin()} --allow-all ${f}')
}

// ── 1. The exact #53 reproducer: recursive impure def + stdlib in the caller ──

fn test_issue53_recursive_impure_then_stdlib() {
	src := "[?lib 'cx-stdlib/strings' :as s]\n" +
		"[?lib 'cx-stdlib/time' :as time]\n" +
		'[?def loop impure (\$n \$acc)\n' +
		'  [?if [<= \$n 0] [then \$acc]\n' +
		'   [else [?let [= \$t [\$time:now]] [loop [- \$n 1] [\$concat \$acc "x"]]]]]]\n' +
		'[?def run impure (\$_)\n' +
		'  [?let [= \$x [loop 3 ""]]\n' +
		'   [?let [= \$len [\$s:length \$x]] [\$concat "len=" \$len]]]]\n' +
		'[run ""]\n'
	r := run_src(src)
	assert r.exit_code == 0, 'exit ${r.exit_code}: ${r.output}'
	assert r.output.trim_space() == "'len=3'", 'expected len=3, got: ${r.output}'
}

// ── 2. Pure self-recursion by bareword head returns the computed value ────────

fn test_bareword_self_recursion() {
	src := '[?def sumto (\$n \$acc) [?if [<= \$n 0] [then \$acc] [else [sumto [- \$n 1] [+ \$acc \$n]]]]]\n[sumto 5 0]\n'
	r := run_src(src)
	assert r.exit_code == 0, 'exit ${r.exit_code}: ${r.output}'
	assert r.output.trim_space() == '15', 'expected 15, got: ${r.output}'
}

// ── 3. Single-arg recursive call with an operator-element argument ────────────

fn test_bareword_single_arg_operator_recursion() {
	src := '[?def cd (\$n) [?if [<= \$n 0] [then :done] [else [cd [- \$n 1]]]]]\n[cd 5]\n'
	r := run_src(src)
	assert r.exit_code == 0, 'exit ${r.exit_code}: ${r.output}'
	assert r.output.trim_space() == ':done', 'expected :done, got: ${r.output}'
}

// ── 4. Mutual recursion by bareword head ──────────────────────────────────────

fn test_bareword_mutual_recursion() {
	src := '[?def ev (\$n) [?if [= \$n 0] [then true] [else [od [- \$n 1]]]]]\n' +
		'[?def od (\$n) [?if [= \$n 0] [then false] [else [ev [- \$n 1]]]]]\n[ev 4]\n'
	r := run_src(src)
	assert r.exit_code == 0, 'exit ${r.exit_code}: ${r.output}'
	assert r.output.trim_space() == 'true', 'expected true, got: ${r.output}'
}

// ── 4b. Zero-arg user-def is callable by its bareword head (#55) ──────────────

fn test_bareword_zero_arg_def_dispatches() {
	// `[?def f () …]` then `[f]` (no args) must RUN f, not construct the data
	// element `[f]`. Before #55 the element-form closure dispatch gated on
	// `items.len >= 1`, so a nullary call fell through to construction → `[f]`.
	src := '[?def f impure () [\$concat "hi-from-" "f"]]\n[f]\n'
	r := run_src(src)
	assert r.exit_code == 0, 'exit ${r.exit_code}: ${r.output}'
	assert r.output.trim_space() == "'hi-from-f'", 'expected hi-from-f, got: ${r.output}'
}

// ── 4c. A bareword that is NOT a def still self-evaluates as a data word ───────

fn test_bareword_nondef_zero_arg_is_data() {
	// The zero-arg widening is gated on `name in env.closures`; an undefined
	// bareword element `[primary]` must remain a data element (homoiconic rule),
	// never an "unknown function" error.
	src := '[?def f impure () "ran"]\n[primary]\n'
	r := run_src(src)
	assert r.exit_code == 0, 'exit ${r.exit_code}: ${r.output}'
	assert r.output.trim_space() == '[primary]', 'expected [primary] data element, got: ${r.output}'
}

// ── 6. #59: a nested USER-DEF call in argument position is APPLIED ─────────────
//
// Same gate as #53: `all_items_are_expr_position`. An argument that is itself a
// bareword element whose head names a registered closure (`[f "a"]`) is a
// value-producing CALL, not a data child. Before the fix `[g [f "a"]]` failed
// the gate → the OUTER `g` fell through to data construction (`[g 'F(a)']`),
// and in stringy callers the downstream stdlib read as a misleading
// `no callable "concat"`. Nested BUILTIN / `$`-calls already applied; this
// restores parity for user defs.

fn test_issue59_nested_userdef_arg_is_applied() {
	src := '[?def f (\$x) [\$concat "F(" \$x ")"]]\n' +
		'[?def g (\$y) [\$concat "G[" \$y "]"]]\n' +
		'[g [f "a"]]\n'
	r := run_src(src)
	assert r.exit_code == 0, 'exit ${r.exit_code}: ${r.output}'
	assert r.output.trim_space() == "'G[F(a)]'", 'expected G[F(a)], got: ${r.output}'
}

fn test_issue59_nested_userdef_arg_numeric() {
	src := '[?def inc (\$x) [+ \$x 1]]\n[?def dbl (\$y) [* \$y 2]]\n[dbl [inc 5]]\n'
	r := run_src(src)
	assert r.exit_code == 0, 'exit ${r.exit_code}: ${r.output}'
	assert r.output.trim_space() == '12', 'expected 12 (dbl(inc(5))), got: ${r.output}'
}

fn test_issue59_three_deep_userdef_nesting() {
	src := '[?def f (\$x) [\$concat "F(" \$x ")"]]\n' +
		'[?def g (\$y) [\$concat "G[" \$y "]"]]\n' +
		'[?def h (\$z) [\$concat "H{" \$z "}"]]\n' +
		'[h [g [f "a"]]]\n'
	r := run_src(src)
	assert r.exit_code == 0, 'exit ${r.exit_code}: ${r.output}'
	assert r.output.trim_space() == "'H{G[F(a)]}'", 'expected H{G[F(a)]}, got: ${r.output}'
}

// A nested non-def element argument still constructs as data (no over-broad
// hijack): `[g [a 1]]` where `a` is not a def keeps `[a 1]` a data child.
fn test_issue59_nested_nondef_arg_stays_data() {
	src := '[?def g (\$y) \$y]\n[g [a 1]]\n'
	r := run_src(src)
	assert r.exit_code == 0, 'exit ${r.exit_code}: ${r.output}'
	assert r.output.contains('[a 1]'), 'nested non-def element must stay data: ${r.output}'
}

// ── 5. A data element whose head is NOT a def still constructs (not hijacked) ──

fn test_data_element_head_not_dispatched() {
	// `widget` is not a [?def] — `[widget …]` must remain data construction even
	// with nested-element children, so the closure-dispatch widening is gated on
	// the head actually being a registered closure.
	f := os.join_path(os.temp_dir(), 'cx_rec_data_${os.getpid()}.cx')
	os.write_file(f, '[widget [child 1] [child 2]]\n') or { panic(err) }
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} --from=cx --to=cx ${f}')
	assert r.exit_code == 0, 'exit ${r.exit_code}: ${r.output}'
	assert r.output.contains('[widget'), 'widget element should construct as data: ${r.output}'
	assert r.output.contains('[child'), 'child elements should be preserved: ${r.output}'
}

// ── source: vcx/tests/purity_checker_test.v ──
// Tests for the Phase 2.22 static purity checker (+
// ). Covers:
//
//   - Pure-by-default def calling another pure def (transitive) → passes.
//   - Pure def calling impure builtin → CXER0233.
//   - Pure def with `[?modify]` directive → CXER0233.
//   - Predicate body calling impure → CXER0230.
//   - `$_position` / `$_last` outside predicate body → CXER0231.
//   - `:bind _` → CXER0232.
//   - Unclassified builtin call → CXER0234.
//   - `:impure` def accepted unconditionally (annotation conservative).
//   - Recursion / self-recursion does not infinite-loop.
//   - check_all walks every def in the module.
//
// The checker reads `def.body` as verbatim source (Phase 2.16 will graft
// a structural ProgramExpr subtree). Tests construct DefNodes directly
// — no parser dependency — so each scenario is a tight, isolated unit.
// ── Helpers ───────────────────────────────────────────────────────────────────

fn mk_def_pure(name string, body string) &cx.DefNode {
	return &cx.DefNode{
		name:   name
		body:   body
		purity: .pure_
	}
}

fn mk_def_impure(name string, body string) &cx.DefNode {
	return &cx.DefNode{
		name:   name
		body:   body
		purity: .impure_
	}
}

// ── Pure-by-default passes ────────────────────────────────────────────────────

fn test_pure_def_calling_pure_def_passes() {
	add := mk_def_pure('add', '[+ a b]')
	caller := mk_def_pure('total', 'add(x, y)')
	checker := code.new_purity_checker([add, caller])
	checker.check_def(caller) or {
		assert false, 'expected pure → pure call to pass, got: ${err.msg()}'
		return
	}
}

fn test_pure_def_with_pure_builtin_passes() {
	d := mk_def_pure('shout', 'upper(text)')
	checker := code.new_purity_checker([d])
	checker.check_def(d) or {
		assert false, 'expected pure builtin call to pass, got: ${err.msg()}'
		return
	}
}

fn test_pure_def_with_no_calls_passes() {
	d := mk_def_pure('answer', '42')
	checker := code.new_purity_checker([d])
	checker.check_def(d) or {
		assert false, 'expected literal body to pass, got: ${err.msg()}'
		return
	}
}

// ── CXER0233: :pure annotation contradicts impure inferred ────────────────────

fn test_pure_def_calling_impure_builtin_raises_cxer0233() {
	d := mk_def_pure('stamp_id', 'concat("id-", uuid())')
	checker := code.new_purity_checker([d])
	checker.check_def(d) or {
		assert err.msg().contains('CXER0233'), 'expected CXER0233, got: ${err.msg()}'
		assert err.msg().contains('uuid'), 'expected callee `uuid` in message, got: ${err.msg()}'
		return
	}
	assert false, 'expected impure-builtin call to raise CXER0233'
}

fn test_pure_def_with_modify_directive_raises_cxer0233() {
	d := mk_def_pure('mut_doc', '[?modify (set @done true)]')
	checker := code.new_purity_checker([d])
	checker.check_def(d) or {
		assert err.msg().contains('CXER0233'), 'expected CXER0233, got: ${err.msg()}'
		assert err.msg().contains('?modify'), 'expected `?modify` in message, got: ${err.msg()}'
		return
	}
	assert false, 'expected [?modify] in pure body to raise CXER0233'
}

fn test_pure_def_calling_impure_def_raises_cxer0233() {
	now_iso := mk_def_impure('now-iso', 'format-instant(now())')
	caller := mk_def_pure('with-timestamp', 'concat(now-iso(), " ", msg)')
	checker := code.new_purity_checker([now_iso, caller])
	checker.check_def(caller) or {
		assert err.msg().contains('CXER0233'), 'expected CXER0233, got: ${err.msg()}'
		return
	}
	assert false, 'expected pure→impure-def call to raise CXER0233'
}

// ── :impure annotation is conservative (accepted unconditionally) ─────────────

fn test_impure_def_with_pure_body_accepted() {
	d := mk_def_impure('maybe_impure', '[+ x 1]')
	checker := code.new_purity_checker([d])
	checker.check_def(d) or {
		assert false, 'expected :impure annotation to accept pure body, got: ${err.msg()}'
		return
	}
}

fn test_impure_def_calling_impure_builtin_accepted() {
	d := mk_def_impure('log-now', 'print(now())')
	checker := code.new_purity_checker([d])
	checker.check_def(d) or {
		assert false, 'expected :impure body with impure callees to pass, got: ${err.msg()}'
		return
	}
}

// ── CXER0230: predicate-body purity ───────────────────────────────────────────

fn test_predicate_body_calling_pure_passes() {
	p := &cx.PredicateExpr{
		kind:   .generic
		source: 'upper(@name)'
	}
	checker := code.new_purity_checker([]&cx.DefNode{})
	checker.check_predicate(p) or {
		assert false, 'expected pure predicate body to pass, got: ${err.msg()}'
		return
	}
}

fn test_predicate_body_calling_impure_builtin_raises_cxer0230() {
	p := &cx.PredicateExpr{
		kind:   .generic
		source: 'eq(@stamp, now())'
	}
	checker := code.new_purity_checker([]&cx.DefNode{})
	checker.check_predicate(p) or {
		assert err.msg().contains('CXER0230'), 'expected CXER0230, got: ${err.msg()}'
		assert err.msg().contains('now'), 'expected `now` in message, got: ${err.msg()}'
		return
	}
	assert false, 'expected impure callee in predicate to raise CXER0230'
}

fn test_predicate_body_calling_impure_directive_raises_cxer0230() {
	p := &cx.PredicateExpr{
		kind:   .generic
		source: '[?send chan x]'
	}
	checker := code.new_purity_checker([]&cx.DefNode{})
	checker.check_predicate(p) or {
		assert err.msg().contains('CXER0230'), 'expected CXER0230, got: ${err.msg()}'
		return
	}
	assert false, 'expected [?send] in predicate body to raise CXER0230'
}

// ── CXER0231: reserved-binding use outside predicate body ─────────────────────

fn test_position_outside_predicate_raises_cxer0231() {
	d := mk_def_pure('weird', '[+ \$_position 1]')
	checker := code.new_purity_checker([d])
	checker.check_def(d) or {
		assert err.msg().contains('CXER0231'), 'expected CXER0231, got: ${err.msg()}'
		assert err.msg().contains('\$_position'), 'expected `\$_position` in message, got: ${err.msg()}'
		return
	}
	assert false, 'expected \$_position outside predicate to raise CXER0231'
}

fn test_last_outside_predicate_raises_cxer0231() {
	checker := code.new_purity_checker([]&cx.DefNode{})
	code.check_reserved_binding_use('[+ \$_last 0]') or {
		assert err.msg().contains('CXER0231'), 'expected CXER0231, got: ${err.msg()}'
		_ = checker
		return
	}
	assert false, 'expected \$_last outside predicate to raise CXER0231'
}

fn test_position_inside_string_literal_does_not_trip_cxer0231() {
	d := mk_def_pure('label', 'concat("position=", "\$_position")')
	checker := code.new_purity_checker([d])
	checker.check_def(d) or {
		assert false, 'expected `\$_position` inside string literal to be ignored, got: ${err.msg()}'
		return
	}
}

// ── CXER0232: reserved :bind _ ────────────────────────────────────────────────

fn test_bind_underscore_raises_cxer0232() {
	code.check_reserved_bind_name('_') or {
		assert err.msg().contains('CXER0232'), 'expected CXER0232, got: ${err.msg()}'
		return
	}
	assert false, 'expected `:bind _` to raise CXER0232'
}

fn test_bind_normal_name_passes() {
	code.check_reserved_bind_name('user') or {
		assert false, 'expected normal bind name to pass, got: ${err.msg()}'
		return
	}
}

// ── CXER0234: unclassified directive ──────────────────────────────────────────

fn test_unclassified_directive_raises_cxer0234() {
	// `?someday` is a hypothetical directive head not in either the pure
	// builtin table nor the impure-directive set; it should surface as
	// CXER0234 per the closed-list discipline.
	d := mk_def_pure('uses_unknown_dir', '[?someday x]')
	checker := code.new_purity_checker([d])
	checker.check_def(d) or {
		assert err.msg().contains('CXER0234'), 'expected CXER0234, got: ${err.msg()}'
		assert err.msg().contains('?someday'), 'expected `?someday` in message, got: ${err.msg()}'
		return
	}
	assert false, 'expected unclassified directive to raise CXER0234'
}

// ── Recursion + check_all ─────────────────────────────────────────────────────

fn test_self_recursion_terminates() {
	// `[?def fact ($n) ... fact(n - 1) ...]` — pure self-recursion must
	// not infinite-loop the walker.
	fact := mk_def_pure('fact', '[?if (eq(n, 0)) 1 [* n fact(n - 1)]]')
	checker := code.new_purity_checker([fact])
	checker.check_def(fact) or {
		assert false, 'expected pure self-recursion to pass, got: ${err.msg()}'
		return
	}
}

fn test_mutual_recursion_terminates() {
	even := mk_def_pure('even', '[?if (eq(n, 0)) true odd(n - 1)]')
	odd := mk_def_pure('odd', '[?if (eq(n, 0)) false even(n - 1)]')
	checker := code.new_purity_checker([even, odd])
	checker.check_def(even) or {
		assert false, 'expected pure mutual recursion to pass, got: ${err.msg()}'
		return
	}
	checker.check_def(odd) or {
		assert false, 'expected pure mutual recursion to pass, got: ${err.msg()}'
		return
	}
}

fn test_check_all_walks_every_def() {
	good := mk_def_pure('good', 'upper(x)')
	bad := mk_def_pure('bad', 'uuid()')
	checker := code.new_purity_checker([good, bad])
	checker.check_all() or {
		assert err.msg().contains('CXER0233'), 'expected CXER0233 from check_all, got: ${err.msg()}'
		return
	}
	assert false, 'expected check_all to surface CXER0233 from `bad`'
}

fn test_check_all_passes_when_every_def_pure() {
	a := mk_def_pure('a', '[+ x 1]')
	b := mk_def_pure('b', 'a(x)')
	checker := code.new_purity_checker([a, b])
	checker.check_all() or {
		assert false, 'expected check_all over pure defs to pass, got: ${err.msg()}'
		return
	}
}

// ── node_calls_impure_builtin — the CXLS005 §7.3 purity gate ───────────────────
// The lint warns on `[par]` only when the body actually CALLS an impure
// builtin; a pure body is safe to parallelize and gets no hint.

fn parse_body(src string) cx.ProgramNode {
	prog := cx.parse_program(src) or { panic('parse failed: ${err.msg()}') }
	return prog.body
}

fn test_node_impure_pure_body_is_pure() {
	// Pure arithmetic / string body → not impure → no CXLS005 hint.
	assert !code.node_calls_impure_builtin(parse_body('[+ 1 2]'))
	assert !code.node_calls_impure_builtin(parse_body('[upper "hi"]'))
}

fn test_node_impure_module_qualified_call_detected() {
	// `env:var` (a $-call) normalizes to the `env-var` purity-table key → impure.
	assert code.node_calls_impure_builtin(parse_body('[$env:var "HOME"]'))
}

fn test_node_impure_directive_head_detected() {
	// An impure directive head ([?async]/[?send]/…) inside the body counts.
	assert code.node_calls_impure_builtin(parse_body('[?async [+ 1 2]]'))
}

fn test_node_impure_nested_in_pure_wrapper_detected() {
	// The walk recurses through pure wrappers to find the impure $-call.
	assert code.node_calls_impure_builtin(parse_body('[?if true [then [$env:var "HOME"]] [else 0]]'))
}

fn test_node_impure_pure_call_body_is_pure() {
	// A body of only pure operator forms is pure → no CXLS005 hint.
	assert !code.node_calls_impure_builtin(parse_body('[?if true [then [+ 1 2]] [else 0]]'))
}

// ── source: vcx/tests/visibility_test.v ──
// Tests for the Phase 2.15 `:scope public/private` visibility
// enforcement surface in `vcx/code/module_loader.v`
// + spec/code.md §12.6.
//
// The visibility rule under test:
//
//   - Module-private is the default. A `[?def]` / `[?const]` with no
//     `:scope` modifier OR with `:scope private` is private.
//   - Only `:scope public` opts a symbol into the import surface.
//   - Same-module reads (Module.lookup_def / lookup_const with
//     `requesting_module == m.name`) resolve regardless of scope.
//   - Cross-module reads require `:scope public`; otherwise the
//     lookup raises MODULE_SYMBOL_NOT_PUBLIC.
//   - MODULE_SYMBOL_NOT_FOUND is the distinct "no such name" error.
//   - `:only (name …)` on `[?lib]` runs the same visibility check at
//     module-load time so a forbidden import fails fast.
//
// All fixtures are synthetic in-process strings via
// `ModuleTable.register_source`.
// ── 1. scope_is_public — none / 'private' / 'public' triage ──────────────────

fn test_visibility_scope_is_public_helper() {
	assert code.scope_is_public(none) == false
	assert code.scope_is_public(?string('private')) == false
	assert code.scope_is_public(?string('public')) == true
}

// ── 2. Public [?def] is visible to importer ──────────────────────────────────

fn test_visibility_public_def_visible_to_importer() {
	mut table := code.new_module_table()
