		panic('expected load success, got: ${err}')
	}
	assert mod_a.is_def_public('helper')
	d := mod_a.lookup_def('helper', 'mod-b') or {
		panic('expected public def to resolve cross-module, got: ${err}')
	}
	assert d.name == 'helper'
}

