// ── source: vcx/tests/meta_test.v ──
// v08_meta_test — D5 (code.md §4.2): `[?meta {…} FORM]` inert value
// annotations + the `[meta-of EXPR]` reflection builtin (Clojure-metadata
// model). The annotation is an inert side-band on the value: rendering is
// transparent, structural equality / EBV / arithmetic read through it, and
// only `meta-of` observes the map. Stacked wraps merge last(outer)-wins.

fn ev(src string) string {
	code.caps_set_all()
	prog := cx.parse_program(src) or { return 'PARSE-ERR: ${err}' }
	mut env := code.new_env()
	res := code.eval(prog.body, mut env) or { return 'EVAL-ERR: ${err}' }
	return code.render_canonical(res).trim_space()
}

// ── inert: [?meta {…} V] returns V unchanged ───────────────────────────────

fn test_meta_is_inert() {
	assert ev('[?meta {author: "ep"} 42]') == '42'
	assert ev('[?meta {pii: true} [user name=ann]]') == '[user name=ann]'
}

// ── meta-of reflects the map; empty map when absent ────────────────────────

fn test_meta_of_reads_map() {
	// #831 (RULED: 831-1a′): `ep` is bare-safe in BOTH readings, so the
	// result image renders it bare — code.md §11.1a R6's rule, which the
	// program renderer now shares with the data emitter instead of quoting
	// unconditionally.
	got := ev('[?let [= $x [?meta {author: "ep", status: :draft} 42]] [meta-of $x]]')
	assert got == '{author: ep, status: :draft}', got
}

fn test_meta_of_absent_is_empty_map() {
	assert ev('[meta-of 7]') == '{}'
	assert ev('[meta-of [user name=ann]]') == '{}'
}

// ── ignored by evaluation: arithmetic / comparison read through ────────────

fn test_meta_transparent_to_arithmetic() {
	assert ev('[+ [?meta {a: 1} 5] 1]') == '6'
}

fn test_meta_ignored_by_equality() {
	// Two values differing ONLY in metadata are `=`.
	assert ev('[= [?meta {a: 1} 5] 5]') == 'true'
	assert ev('[= [?meta {a: 1} 5] [?meta {b: 2} 5]]') == 'true'
}

// ── stacked wraps merge into one flat map, last(outer)-wins ────────────────

fn test_meta_merge_last_wins() {
	got := ev('[?let [= $x [?meta {a: 1} [?meta {a: 2, b: 3} 9]]] [meta-of $x]]')
	assert got == '{a: 1, b: 3}', got
}

// ── annotation must be a map ───────────────────────────────────────────────

fn test_meta_requires_map() {
	r := ev('[?meta 5 9]')
	assert r.contains('CXER0100'), r
}

// ── meta rides through a binding (the value is reflectable later) ──────────

fn test_meta_rides_through_binding() {
	got := ev('[?let [= $p [?meta {unit: :years} 30]] [meta-of $p]]')
	assert got == '{unit: :years}', got
}

// ── D5: `<cx:meta>` XML serialization (emit) ───────────────────────────────

fn xml(src string) string {
	code.caps_set_all()
	return (code.eval_code('', src, 'xml') or { 'ERR: ${err}' }).trim_space()
}

fn test_meta_xml_emit_element_inner() {
	got := xml('[?meta {pii: true} [user name=ann]]')
	assert got.contains('<cx:meta>'), got
	assert got.contains('<cx:map>'), got
	assert got.contains('<cx:entry cx:key="pii">true</cx:entry>'), got
	assert got.contains('<user name="ann"/>'), got
}

fn test_meta_xml_emit_scalar_inner() {
	got := xml('[?meta {unit: :years} 331]')
	// `<cx:meta>` wraps the map + the scalar. Per @CHOICE-1 (slice A) a discrete
	// typed (non-string) scalar in a multi-item body serializes to its `<cx:TYPE>`
	// carrier — `<cx:int>331</cx:int>` — so the int type round-trips losslessly
	// (the old bare `331` re-parsed as text).
	assert got == '<cx:meta><cx:map><cx:entry cx:key="unit">years</cx:entry></cx:map><cx:int>331</cx:int></cx:meta>', got
}

fn test_no_meta_no_wrapper() {
	got := xml('[user name=ann]')
	assert got == '<user name="ann"/>', got
}

// ── source: vcx/tests/defenses_test.v ──
// Tests for v3.4 adversarial defenses. spec/policies.md §5.
// ── Recursion depth limit ────────────────────────────────────────────────────

fn test_parser_rejects_excessive_nesting() {
	// Build deeply nested CX exceeding max_recursion_depth (64).
	// Stack-overflow without the depth check.
	mut src := ''
	mut close := ''
	for _ in 0 .. 200 {
		src += '[a '
		close += ']'
	}
	src += close
	if _ := cx.parse(src) {
		assert false, 'parser should reject 200-deep nesting'
	} else {
		assert err.msg().contains('nesting'),
			'expected nesting-related error, got: ${err.msg()}'
	}
}

fn test_parser_accepts_bounded_nesting() {
	// 32 levels deep — well under the 64 limit.
	mut src := ''
	mut close := ''
	for _ in 0 .. 32 {
		src += '[a '
		close += ']'
	}
	src += close
	doc := cx.parse(src) or {
		assert false, 'bounded nesting should parse cleanly: ${err.msg()}'
		return
	}
	root := doc.root() or { panic('no root') }
	assert root.name == 'a'
}

// ── Bounds checks in binary readers (already covered in 2b/2c) ───────────────
// See vcx/tests/data_bin_test.v and vcx/tests/ast_bin_test.v
// for length-prefix bounds-check tests on the binary readers.

// ── source: vcx/tests/secret_redaction_test.v ──
// ── Secret redaction at the structured output boundaries ─────────────────────
//
// cxdm.md §12.2 mandates that a secret value (`[?secret EXPR]`) renders as
// the redaction marker `‹redacted›` — never the underlying value — at
// EVERY emit boundary. The canonical / text / cx boundary is gated by the
// `program-secret-002/003/005` cases in conformance/code.cxd (the eval
// fixture gate renders via render_canonical). This test covers the
// structured normalizers the .cxd gate cannot reach: JSON / YAML / XML /
// CSV (and re-checks canonical here too for locality).
//
// Invariant for every target: the marker is present and the cleartext
// `sk-abc` is absent. Reveal (declassify) is gated by the `secret-reveal`
// capability and is exercised by program-secret-004.

const secret_program = '[credentials [token [?secret sk-abc]]]'

fn eval_to(program string, target string) string {
	mut env := code.new_env()
	code.caps_set_all()
	prog := cx.parse_program(program) or { return 'PARSE-ERR: ${err}' }
	result := code.eval(prog.body, mut env) or { return 'EVAL-ERR: ${err}' }
	return code.render(result, target) or { return 'RENDER-ERR: ${err}' }
}

fn assert_redacted(target string, out string) {
	assert out.contains('‹redacted›'), '${target}: expected redaction marker, got: ${out}'
	assert !out.contains('sk-abc'), '${target}: leaked cleartext secret, got: ${out}'
}

fn test_secret_redacted_canonical() {
	out := eval_to(secret_program, 'cx')
	assert_redacted('cx', out)
}

fn test_secret_redacted_text() {
	out := eval_to(secret_program, 'text')
	assert_redacted('text', out)
}

fn test_secret_redacted_json() {
	out := eval_to(secret_program, 'json')
	assert_redacted('json', out)
}

fn test_secret_redacted_yaml() {
	out := eval_to(secret_program, 'yaml')
	assert_redacted('yaml', out)
}

fn test_secret_redacted_xml() {
	out := eval_to(secret_program, 'xml')
	assert_redacted('xml', out)
}

// CSV: a sequence-of-records where one record holds a secret-bearing
// attribute. The secret is a body child here, so it surfaces as a row
// value; the marker must appear and the cleartext must not.
fn test_secret_redacted_csv() {
	// (row with a secret child) — a uniform single-column record set.
	out := eval_to('({secret-col: [?secret sk-abc]})', 'csv')
	// CSV extraction may reject the shape; what matters is no cleartext
	// EVER reaches the wire. If a value column is produced it must be the
	// marker.
	assert !out.contains('sk-abc'), 'csv: leaked cleartext secret, got: ${out}'
}

// Top-level bare secret redacts to the quoted marker in canonical form.
fn test_secret_top_level_canonical() {
	out := eval_to('[?secret sk-abc]', 'cx')
	assert out.trim_space() == "'‹redacted›'", 'top-level canonical: got ${out}'
}

// A revealed secret (declassified under secret-reveal, granted by
// caps_set_all here) is NOT redacted — the cleartext is the whole point of
// declassification (cxdm.md §12.3).
fn test_revealed_secret_is_cleartext() {
	out := eval_to('[?reveal [?secret sk-abc]]', 'text')
	assert out.trim_space() == 'sk-abc', 'reveal: expected cleartext, got ${out}'
}

// ── source: vcx/tests/random_streams_test.v ──
// random_streams_test.v — #625: the implicit PRNG is one stream PER THREAD
// (spec random.md §2) and stateful generator handles (§3.7) are private
// deterministic streams. Pre-fix, one process-global Xoshiro raced across
// [?worker] threads: two workers that each seed(42)+draw interleaved on the
// shared state and produced different outputs run to run — the #625
// deterministic-generation failure.

fn rs_run(prog string) string {
	tmp := os.join_path(os.temp_dir(), 'cx-rand-${os.getpid()}-${time.now().unix_nano()}.cx')
	os.write_file(tmp, prog) or { panic(err) }
	defer {
		os.rm(tmp) or {}
	}
	res := os.execute('CX_WORKER_THREADS=4 ${testenv.cx_bin()} ${tmp}')
	return res.output.trim_space()
}

const golden_42 = '7510639304993616975' // the pinned §4.1 seed-42 first draw

fn test_worker_seed_and_draw_is_deterministic() {
	prog := "[?lib 'cx-stdlib/random' :as random]
[?let
  [= \$w1 [?worker name='w1' [?let [= \$s [\$random:seed 42]] [\$random:next-int]]]]
  [= \$w2 [?worker name='w2' [?let [= \$s [\$random:seed 42]] [\$random:next-int]]]]
  [= \$v1 [?wait-for [worker \$w1]]]
  [= \$v2 [?wait-for [worker \$w2]]]
  [out [?str '{\$v1}|{\$v2}']]]
"
	// three runs: both workers always produce the pinned value — no cross-
	// worker interleaving, no run-to-run drift.
	for i in 0 .. 3 {
		out := rs_run(prog)
		assert out.contains('${golden_42}|${golden_42}'), 'worker draw not deterministic (run ${i}): ${out}'
	}
}

fn test_worker_draws_do_not_perturb_main_stream() {
	prog := "[?lib 'cx-stdlib/random' :as random]
[?let
  [= \$s [\$random:seed 42]]
  [= \$w [?worker name='noise' [\$random:next-ints 64]]]
  [= \$sync [?wait-for [worker \$w]]]
  [out [\$random:next-int]]]
"
	out := rs_run(prog)
	assert out.contains(golden_42), 'a worker draining ITS stream must not advance the main thread stream: ${out}'
}

fn test_handle_draw_on_freed_handle_refuses() {
	prog := "[?lib 'cx-stdlib/random' :as random]
[?let
  [= \$g [\$random:new 7]]
  [= \$v [\$random:gen-int \$g]]
  [= \$f [\$random:free \$g]]
  [out [\$random:gen-int \$g]]]
"
	out := rs_run(prog)
	assert out.contains('CXER1906'), 'a draw on a freed handle must refuse with E_RANDOM_HANDLE_INVALID: ${out}'
}

fn test_handles_are_concurrency_safe_private_streams() {
	// 4 workers share ONE handle: draws serialize (no crash / no torn state)
	// and drain exactly the handle's seeded sequence — the union of the
	// workers' draws equals the single-threaded prefix of the same length.
	prog := "[?lib 'cx-stdlib/random' :as random]
[?let
  [= \$g [\$random:new 42]]
  [= \$w1 [?worker name='a' [\$random:gen-ints \$g 50]]]
  [= \$w2 [?worker name='b' [\$random:gen-ints \$g 50]]]
  [= \$r1 [?wait-for [worker \$w1]]]
  [= \$r2 [?wait-for [worker \$w2]]]
  [= \$ref [\$random:gen-ints [\$random:new 42] 100]]
  [= \$all [?for [in \$v (\$r1, \$r2)] [yield \$v]]]
  [= \$n [\$count \$all]]
  [out [?str '{\$n}|{[\$cx:equal [\$sort \$all] [\$sort \$ref]]}']]]
"
	out := rs_run(prog)
	// sorted equality is order-independent: the two workers' interleaved
	// draws drain EXACTLY the handle's seeded 100-draw prefix, partitioned —
	// no torn state, no duplicated or lost draws.
	assert out.contains('100|true'), 'concurrent draws on one handle must drain exactly its seeded sequence: ${out}'
}

// ── source: vcx/tests/effect_alignment_test.v ──
// effect_alignment_test.v — the §6.5.1 capability-alignment gate
// (spec/core/code.md §6.5.1; SAP §4.1 ALIGNMENT; D010).
//
// Enforces BOTH directions of the ONE-WAY invariant + drift canaries:
//
//   (1) gated ⇒ impure : every capability_gated_prims() key is classified
//       impure by the closed §6.5.x purity table.
//   (2) closed exception table : every impure entry of the purity table is
//       EITHER capability-gated OR in the closed exception buckets.
//   (3) drift canaries : the gated map agrees with the LIVE dispatcher lists
//       (process- prefix, env- minus env_pure_prims, io read+write+open),
//       so the table cannot silently drift from the guards it mirrors.
//
// The maps are owned by effect_alignment.v (one source of truth shared by
// the checker fold and this gate).
// ── (1) gated ⇒ impure ─────────────────────────────────────────────────────────

fn test_every_gated_prim_is_impure() {
	// BOTH halves of the mirror (#827) — a Ring-2 effect point is no less an
	// effect point, so direction 1 covers it too.
	mut gated := code.capability_gated_prims().clone()
	for prim, cap in platform.platform_capability_gated_prims() {
		gated[prim] = cap
	}
	assert gated.len > 0, 'the gated mirror is empty — the gate has nothing to enforce'
	mut violations := []string{}
	for prim, cap in gated {
		if !code.builtin_is_impure(prim) {
			violations << '${prim} (gated under `${cap}`) is NOT classified impure'
		}
	}
	assert violations.len == 0, 'direction-1 (gated ⇒ impure) violations:\n  ' +
		violations.join('\n  ')
}

// ── (2) every impure entry is gated OR in the closed exception table ───────────

fn test_every_impure_is_gated_or_excepted() {
	gated := code.capability_gated_prims()
	exceptions := code.impure_without_capability_exceptions()
	impure := code.impure_builtin_names()
	assert impure.len > 0, 'no impure builtins — the purity table is empty'
	mut orphans := []string{}
	for prim in impure {
		if prim in gated {
			continue
		}
		if prim in exceptions {
			continue
		}
		orphans << prim
	}
	assert orphans.len == 0,
		'direction-2 violation — impure-without-capability builtins missing from the closed exception table:\n  ' +
		orphans.join('\n  ') +
		'\n(either gate them with cap_guard, or add an exception row in effect_alignment.v)'
}

// The exception table must be CLOSED: no entry that is also gated (an entry
// cannot be both), and no entry that is not actually impure.
fn test_exception_table_is_closed_and_consistent() {
	gated := code.capability_gated_prims()
	exceptions := code.impure_without_capability_exceptions()
	for prim, _ in exceptions {
		assert prim !in gated,
			'`${prim}` is in BOTH the gated map and the exception table — it cannot be both'
		assert code.builtin_is_impure(prim),
			'`${prim}` is in the impure-without-capability exception table but is NOT classified impure'
	}
}

// ── (3) drift canaries ─────────────────────────────────────────────────────────

// Every gated `process-` prim is the whole process- prefix (the dispatcher
// gates the prefix), and every purity-table `process-` name is gated.
fn test_process_prefix_fully_gated() {
	gated := code.capability_gated_prims()
	for prim in code.impure_builtin_names() {
		if prim.starts_with('process-') {
			assert prim in gated,
				'`${prim}` starts with `process-` but is not in the gated map (process- is prefix-gated)'
			assert gated[prim] == 'subprocess',
				'`${prim}` should be gated under `subprocess`, got `${gated[prim]}`'
		}
	}
}

// Every gated `env-` prim is an env- name NOT in env_uncapped_prims, charged
// under `env` (environment/identity) or `read` (cwd / executable-path
// filesystem-layout disclosure, env.md §7); and no uncapped name is gated.
fn test_env_gating_excludes_pure_prims() {
	gated := code.capability_gated_prims()
	pure_prims := code.alignment_env_pure_prims()
	read_prims := ['env-cwd', 'env-executable-path']
	for prim, cap in gated {
		if prim.starts_with('env-') {
			assert prim !in pure_prims,
				'`${prim}` is in the gated map but is a capability-free env name (env_uncapped_prims)'
			expected_cap := if prim in read_prims { 'read' } else { 'env' }
			assert cap == expected_cap,
				'`${prim}` should be gated under `${expected_cap}`, got `${cap}`'
		}
	}
	for pure_prim in pure_prims {
		assert pure_prim !in gated,
			'uncapped env name `${pure_prim}` must NOT be capability-gated'
	}
}

// The gated io surface == io_read_caps ∪ io_write_caps ∪ {io-open} ∪ the
// self-gating watch pair (io-watch/io-watch-next, iowatch_ring2_builtin —
// added to the alignment map at stream 6's EV-EFFECT-SET move: they were
// previously outside BOTH directions, the drift-canary hole).
fn test_io_gated_set_matches_dispatcher_lists() {
	gated := code.capability_gated_prims()
	mut expected := map[string]bool{}
	for n in code.alignment_io_read_caps() {
		expected[n] = true
	}
	for n in code.alignment_io_write_caps() {
		expected[n] = true
	}
	expected['io-open'] = true
	expected['io-watch'] = true
	expected['io-watch-next'] = true

	// Every expected io prim is gated.
	for prim, _ in expected {
		assert prim in gated, 'io prim `${prim}` (dispatcher list) is not in the gated map'
	}
	// Every gated io- prim is expected (no extras, no drift).
	for prim, _ in gated {
		if prim.starts_with('io-') {
			// io-edit-file requires BOTH read and write and self-guards at
			// its dispatch site, so it deliberately rides neither prim list
			// (#827; the §2.1 scoping note records the same shape).
			if prim == 'io-edit-file' {
				continue
			}
			assert prim in expected,
				'gated io prim `${prim}` is not in io_read_caps ∪ io_write_caps ∪ {io-open}'
		}
	}
}

// Sanity: the four cap-gated path/store/i18n/testkit singletons are present
// and impure (these are the C2 additions that previously defaulted pure).
fn test_c2_newly_classified_singletons() {
	for prim in ['path-absolute', 'path-canonical', 'i18n-load-catalog',
		'test-fixture-load', 'store-open', 'store-open-opts'] {
		assert code.builtin_is_impure(prim),
			'`${prim}` must be classified impure (it is capability-gated)'
		assert prim in code.capability_gated_prims(), '`${prim}` must be in the gated map'
	}
	// `test-fixture` (the in-memory, ungated sibling) must NOT be gated.
	assert 'test-fixture' !in code.capability_gated_prims(),
		'`test-fixture` builds an in-memory sequence with no cap_guard — it must not be gated'
}

// ── stream 6 (#678, EV-EFFECT-SET): the spec table is the source of truth ──
// security.md §2.1 holds the NORMATIVE closed effect-point table; the
// implementation map (effect_alignment.v capability_gated_prims()) is its
// conformance MIRROR. This gate asserts spec ↔ implementation equality in
// BOTH directions, so neither can drift: adding an effect point requires a
// spec row first (the clean-room bar — a clause checkable only against a V
// file is not checkable at all).
fn test_effect_point_table_matches_spec() {
	spec_path := os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'spec',
		'03-approved', 'core', 'security.md'))
	text := os.read_file(spec_path) or {
		assert false, 'cannot read security.md for the EV-EFFECT-SET gate: ${err}'
		return
	}
	start := text.index('### §2.1') or {
		assert false, 'security.md §2.1 (the closed effect-point table) is missing'
		return
	}
	rest := text[start..]
	end_rel := rest.index('\n## ') or { rest.len }
	section := rest[..end_rel]
	mut spec_map := map[string]string{}
	for line in section.split_into_lines() {
		l := line.trim_space()
		if !l.starts_with('| `') {
			continue
		}
		cells := l.split('|')
		if cells.len < 3 {
			continue
		}
		prim_cell := cells[1].trim_space()
		cap_cell := cells[2].trim_space()
		if !prim_cell.starts_with('`') || !cap_cell.starts_with('`') {
			continue
		}
		prim := prim_cell.all_after('`').all_before('`')
		cap := cap_cell.all_after('`').all_before('`')
		if prim.len == 0 || cap.len == 0 {
			continue
		}
		spec_map[prim] = cap
	}
	assert spec_map.len > 0, 'parsed zero rows from security.md §2.1 — the gate has nothing to enforce'
	// The mirror has TWO halves (#827). Ring 1's map cannot carry the gated
	// socket surface — that lives in Ring 2, and Ring 1 may not import Ring 2
	// (cx_partition.md §3). The gate unions them here instead, which is
	// legitimate precisely because tests may import anything (§3); the import
	// contract is not bent to make this convenient.
	mut gated := code.capability_gated_prims().clone()
	for prim, cap in platform.platform_capability_gated_prims() {
		assert prim !in gated,
			'`${prim}` is gated in BOTH halves of the mirror — one effect point, one home'
		gated[prim] = cap
	}
	// direction A: every spec row is implemented with the same capability.
	for prim, cap in spec_map {
		assert prim in gated,
			'security.md §2.1 lists `${prim}` but no half of the mirror gates it — implement (or the spec row is stale)'
		assert gated[prim] == cap,
			'`${prim}`: spec says capability `${cap}`, implementation charges `${gated[prim]}`'
	}
	// direction B: every implemented effect point has a spec row.
	for prim, cap in gated {
		assert prim in spec_map,
			'the mirror gates `${prim}` (cap `${cap}`) but security.md §2.1 has no row — the spec table is normative and closed: add the row first (RULED tables-1a)'
	}
}

// ── source: vcx/tests/pereference_test.v ──
// Pass-2 D-I — PEReference node in the DOCTYPE internal subset.
//
// Per spec/core/grammar.ebnf [38]/[39]/[68]: the DTD internal subset is
// stored VERBATIM; a parameter-entity reference `%name;` appears as a
// DeclSep and is kept as an OPAQUE PEReferenceNode — never expanded —
// so it round-trips unchanged to both CX and XML. This fixes the prior
// defect where a `%name;` broke the CX parse loop (and was silently
// dropped char-by-char by the XML reader).

const dtd_cx = "[!DOCTYPE doc [
  [!ENTITY % common 'name CDATA #IMPLIED']
  %common;
  [!ELEMENT doc (#PCDATA)]
]]
"

// ── 1. CX parse stores a PEReferenceNode in the int subset ───────────────────

fn test_cx_parse_keeps_pe_reference_node() {
	doc := cx.parse(dtd_cx) or {
		assert false, 'parse failed: ${err}'
		return
	}
	dt := doc.doctype or {
		assert false, 'no doctype parsed'
		return
	}
	mut pe_count := 0
	mut pe_name := ''
	for n in dt.int_subset {
		if n is cx.PEReferenceNode {
			pe_count++
			pe_name = n.name
		}
	}
	assert pe_count == 1, 'expected exactly 1 PEReferenceNode, got ${pe_count}'
	assert pe_name == 'common', 'expected PEReference name "common", got "${pe_name}"'
}

// ── 2. CX → CX round-trip preserves `%common;` verbatim ──────────────────────

fn test_cx_roundtrip_preserves_pe_reference() {
	doc := cx.parse(dtd_cx) or {
		assert false, 'parse failed: ${err}'
		return
	}
	out := cx.emit_cx(doc)
	assert out.contains('%common;'), 'PEReference dropped on CX emit: ${out}'
	// Re-parse the emitted text — idempotent round-trip.
	doc2 := cx.parse(out) or {
		assert false, 're-parse failed: ${err}'
		return
	}
	assert cx.emit_cx(doc2) == out, 'CX round-trip not idempotent'
}

// ── 3. CX → XML emits `%common;` (mirrors XML's PEReference) ─────────────────

fn test_cx_to_xml_emits_pe_reference() {
	doc := cx.parse(dtd_cx) or {
		assert false, 'parse failed: ${err}'
		return
	}
	xml := cx.emit_xml(doc)
	assert xml.contains('%common;'), 'PEReference not emitted to XML: ${xml}'
	assert xml.contains('<!DOCTYPE doc'), 'doctype not emitted to XML: ${xml}'
}

// ── 4. XML reader preserves a `%name;` PEReference (was dropped before) ──────

fn test_xml_reader_preserves_pe_reference() {
	xml_src := '<!DOCTYPE doc [
  <!ENTITY % common "name CDATA #IMPLIED">
  %common;
  <!ELEMENT doc (#PCDATA)>
]>
<doc/>'
	doc := cx.parse_xml(xml_src) or {
		assert false, 'xml parse failed: ${err}'
		return
	}
	dt := doc.doctype or {
		assert false, 'no doctype parsed from XML'
		return
	}
	mut found := false
	for n in dt.int_subset {
		if n is cx.PEReferenceNode {
			found = found || n.name == 'common'
		}
	}
	assert found, 'XML reader dropped the %common; PEReference'
}

// ── 5. A `%name;` with no semicolon is a parse error ─────────────────────────

fn test_cx_pe_reference_requires_semicolon() {
	bad := '[!DOCTYPE doc [\n  %common\n]]\n'
	if _ := cx.parse(bad) {
		assert false, 'expected parse error for unterminated PEReference'
	}
}

// ── source: vcx/tests/type_strict_validator_test.v (re-authored W5) ──
// The strict dial (spec/code.md §12.7; stream 16 W5): --strict is the
// ONE entry point; CX_STRICT_TYPES and the declaration-PRESENCE
