// ═══ cx schema infer — corpus shape synthesis (shape_inference.md §8, ═══
// stream 16 W3). The join lattice, determinism, and the correctness
// property validate(docs, infer(docs)) = clean.

fn infer_docs(srcs []string) []cx.Document {
	mut docs := []cx.Document{}
	for s in srcs {
		docs << cx.parse(s) or { panic(err) }
	}
	return docs
}

fn test_infer_int_float_joins_to_float() {
	// Plain `2.5` is DECIMAL (exact-by-default); float spells `2.5e0`.
	docs := infer_docs(['[m [v 1]]', '[m [v 2.5e0]]'])
	s := cx.schema_infer(docs, cx.SchemaInferOpts{}) or { panic(err) }
	assert s.contains('[body float [req]]'), s
	assert !s.contains('[or'), s
}

fn test_infer_decimal_joins_only_decimal() {
	// decimal ⊔ decimal → decimal; decimal ⊔ float → [or …], never a
	// numeric collapse (stream 11's no-mixing rule).
	d1 := infer_docs(['[m [v 1.50]]', '[m [v 2.25]]'])
	s1 := cx.schema_infer(d1, cx.SchemaInferOpts{}) or { panic(err) }
	assert s1.contains('[body decimal [req]]'), s1
	d2 := infer_docs(['[m [v 1.50]]', '[m [v 2.5e0]]'])
	s2 := cx.schema_infer(d2, cx.SchemaInferOpts{}) or { panic(err) }
	assert s2.contains('[body [or decimal float] [req]]'), s2
}

fn test_infer_never_widens_to_string() {
	docs := infer_docs(['[m [v 1]]', "[m [v 'x']]"])
	s := cx.schema_infer(docs, cx.SchemaInferOpts{}) or { panic(err) }
	assert s.contains('[body [or int string] [req]]'), s
}

fn test_infer_attr_optionality_and_join() {
	docs := infer_docs(['[m a=1 b=2]', '[m a=3.5e0]'])
	s := cx.schema_infer(docs, cx.SchemaInferOpts{}) or { panic(err) }
	assert s.contains('[attr a::float [req]]'), s
	assert s.contains('[attr b::int [opt]]'), s
}

fn test_infer_cardinality_from_observed_counts() {
	docs := infer_docs(['[o [line 1] [line 2] [line 3]]', '[o [line 1]]', '[o]'])
	s := cx.schema_infer(docs, cx.SchemaInferOpts{}) or { panic(err) }
	assert s.contains('[elem line [card "0..3"]]'), s
}

fn test_infer_container_bodies_join_itemwise() {
	// arr ⊔ arr joins ITEMS (never textual members): [list int] ⊔
	// [list float] → [list float].
	docs := infer_docs(['[m [v [1, 2]]]', '[m [v [2.5e0]]]'])
	s := cx.schema_infer(docs, cx.SchemaInferOpts{}) or { panic(err) }
	assert s.contains('[body [list float] [req]]'), s
}

fn test_infer_determinism_and_e2_identity() {
	srcs := ['[o sku=SKU-1 [line q=1]]', '[o sku=SKU-2 [line q=2] [line q=3]]']
	a := cx.schema_infer(infer_docs(srcs), cx.SchemaInferOpts{}) or { panic(err) }
	b := cx.schema_infer(infer_docs(srcs), cx.SchemaInferOpts{}) or { panic(err) }
	assert a == b
	ha := cx.schema_content_hash(a) or { panic(err) }
	hb := cx.schema_content_hash(b) or { panic(err) }
	assert ha == hb
}

fn test_infer_mixed_roots_refused() {
	docs := infer_docs(['[order]', '[invoice]'])
	if _ := cx.schema_infer(docs, cx.SchemaInferOpts{}) {
		assert false, 'mixed roots must refuse'
	}
}

fn test_infer_sampling_provenance() {
	docs := infer_docs(['[m [v 1]]', "[m [v 'x']]"])
	s := cx.schema_infer(docs, cx.SchemaInferOpts{ sample: 1 }) or { panic(err) }
	assert s.contains('sample="1/2"'), s
	// Only the first doc was seen — the body stays int.
	assert s.contains('[body int [req]]'), s
}

fn test_infer_validate_round_trip_clean() {
	// The §8 correctness property: validate(docs, infer(docs)) → zero
	// diagnostics, across the lattice's shapes.
	corpora := [
		['[m [v 1]]', '[m [v 2.5e0]]'],
		['[m [v 1]]', "[m [v 'x']]"],
		['[o sku=SKU-1 n=1 [line q=1 [note ok]]]', '[o sku=SKU-2 [line q=2.5e0] [line q=3]]'],
		['[m [v [1, 2]]]', '[m [v [2.5]]]'],
		['[m [tags (:a, :b)]]', '[m [tags (:c)]]'],
		['[cfg [opts {retries: 3, host: h1}]]', '[cfg [opts {retries: 5}]]'],
	]
	for srcs in corpora {
		docs := infer_docs(srcs)
		schema := cx.schema_infer(docs, cx.SchemaInferOpts{}) or { panic(err) }
		for i, d in docs {
			rep := cx.validate(d, schema) or { panic(err) }
			assert rep.is_valid(), 'corpus doc ${i} vs inferred schema: ${rep.diagnostics.map(it.code + " " + it.message)}\nschema:\n${schema}'
		}
	}
}

// ═══ W4 — the schema registry re-rule (shape_inference.md §3, L63): ═══
// cx.lock [schemas] pins + CX_SCHEMA_STORE content resolution,
// fail-closed at every hop.

fn test_schema_registry_lock_pin_resolution() {
	// A name with NO in-process binding resolves through the module's
	// cx.lock [schemas] pin; the content arrives via CX_SCHEMA_STORE.
	dir := os.join_path(os.temp_dir(), 'cx_w4_lockpin_${os.getpid()}')
	store := os.join_path(dir, 'store')
	os.mkdir_all(dir) or { panic(err) }
	defer { os.rmdir_all(dir) or {} }
	schema_text := '[schema of=ports mode=open]\n[ports [body [list u16] [req]]]\n'
	canonical := cx.cx_text_canonical(schema_text) or { panic(err) }
	hash := (cx.schema_content_hash(schema_text) or { panic(err) }).hex()
	spath := os.join_path(store, hash[..2], hash + '.cxs')
	os.mkdir_all(os.dir(spath)) or { panic(err) }
	os.write_file(spath, canonical) or { panic(err) }
	os.write_file(os.join_path(dir, 'cx.lock'), '[cx.lock version="1"\n  [schemas\n    [schema name="Ports" hash="${hash}"]]]\n') or { panic(err) }
	prog := "[?lib 'cx-stdlib/validate']\n[\$validate:is-ok [\$validate:validate-against [ports [80, 443]] \"Ports\"]]\n"
	os.write_file(os.join_path(dir, 'main.cx'), prog) or { panic(err) }
	res := os.execute('cd ${dir} && CX_SCHEMA_STORE=${store} ${cx_binary()} main.cx')
	assert res.output.trim_space() == 'true', res.output
}

fn test_schema_registry_poisoned_store_fails_closed() {
	// Store content that fails hash self-verification NEVER resolves —
	// the pin exists, the file exists, but the bytes are not the
	// identity: CXER1600 (the 0x12 rule generalized).
	dir := os.join_path(os.temp_dir(), 'cx_w4_poison_${os.getpid()}')
	store := os.join_path(dir, 'store')
	os.mkdir_all(dir) or { panic(err) }
	defer { os.rmdir_all(dir) or {} }
	schema_text := '[schema of=ports mode=open]\n[ports [body [list u16] [req]]]\n'
	hash := (cx.schema_content_hash(schema_text) or { panic(err) }).hex()
	spath := os.join_path(store, hash[..2], hash + '.cxs')
	os.mkdir_all(os.dir(spath)) or { panic(err) }
	// Poison: different schema bytes under the pinned hash.
	os.write_file(spath, '[schema of=ports mode=open]\n[ports [body [list string] [req]]]\n') or { panic(err) }
	os.write_file(os.join_path(dir, 'cx.lock'), '[cx.lock version="1"\n  [schemas\n    [schema name="Ports" hash="${hash}"]]]\n') or { panic(err) }
	prog := "[?lib 'cx-stdlib/validate']\n[\$validate:validate-against [ports [80, 443]] \"Ports\"]\n"
	os.write_file(os.join_path(dir, 'main.cx'), prog) or { panic(err) }
	res := os.execute('cd ${dir} && CX_SCHEMA_STORE=${store} ${cx_binary()} main.cx')
	assert res.output.contains('CXER1600'), res.output
	// (top-level exit semantics for RETURNED err values is its own
	// settled surface — the value contract is what this fixture pins)
}

fn test_schema_registry_store_write_and_readback() {
	// register-schema persists to CX_SCHEMA_STORE (cache-write); a
	// SECOND process resolves the same name via its lock pin + store.
	dir := os.join_path(os.temp_dir(), 'cx_w4_storerw_${os.getpid()}')
	store := os.join_path(dir, 'store')
	os.mkdir_all(store) or { panic(err) }
	defer { os.rmdir_all(dir) or {} }
	reg := "[?lib 'cx-stdlib/validate']\n[\$validate:register-schema \"P\" \"[schema of=ports mode=open]\n[ports [body [list u16] [req]]]\"]\n"
	os.write_file(os.join_path(dir, 'reg.cx'), reg) or { panic(err) }
	r1 := os.execute('cd ${dir} && CX_SCHEMA_STORE=${store} ${cx_binary()} reg.cx')
	assert r1.exit_code == 0, r1.output
	hash := r1.output.trim_space().trim("'")
	os.write_file(os.join_path(dir, 'cx.lock'), '[cx.lock version="1"\n  [schemas\n    [schema name="P" hash="${hash}"]]]\n') or { panic(err) }
	use := "[?lib 'cx-stdlib/validate']\n[\$validate:is-ok [\$validate:validate-against [ports [80]] \"P\"]]\n"
	os.write_file(os.join_path(dir, 'use.cx'), use) or { panic(err) }
	r2 := os.execute('cd ${dir} && CX_SCHEMA_STORE=${store} ${cx_binary()} use.cx')
	assert r2.output.trim_space() == 'true', r2.output
}

// ── #788 (batch #796): the Ring-2 impure-registration PARITY GATE ───────
// POST-APPLY umbrella addition — not in
// scripts/consolidation/eval_semantics.files; reconcile it into the
// manifest inputs before any future regeneration.
//
// The defect (found by stream 10's anti-2PC corpus row, #682): an
// UNCLASSIFIED callee defaults to PURE. A fold reducer reaching a Ring-2
// verb therefore slipped the CXER4611 guard and deadlocked on the pack's
// own non-reentrant mutex instead of refusing loud. The journal + store
// packs registered their impure verb lists; every other Ring-2 pack was
// still unclassified.
//
// This gate makes the classification self-checking rather than trusting a
// hand-kept list. The invariant, stated over the SOURCE OF TRUTH (each
// wrapping [?def]'s own declared purity in stdlib/*.cx):
//
//   a def declared `impure` must reach at least one callee the engine
//   CLASSIFIES impure
//
// If it does not, the engine reads that def's body as pure — which is
// precisely the slip: the declaration says impure, the classifier says
// pure, and a pure-required context admits it. The check runs through the
// real module loader and the real purity classifier (no regex, no second
// parser), so a newly added Ring-2 verb that nobody registers fails here
// instead of deadlocking in production.
fn ring2_parity_stdlib_files() []string {
	dir := os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'stdlib'))
	entries := os.ls(dir) or { return []string{} }
	mut out := []string{}
	for e in entries {
		if e.ends_with('.cx') {
			out << os.join_path(dir, e)
		}
	}
	out.sort()
	return out
}


fn test_ring2_impure_registration_parity() {
	files := ring2_parity_stdlib_files()
	assert files.len > 0, 'no stdlib/*.cx modules found — the gate must not pass vacuously'
	mut checked := 0
	mut unclassified := []string{}
	for path in files {
		src := os.read_file(path) or {
			assert false, 'read ${path}: ${err}'
			continue
		}
		mod_name := os.file_name(path).all_before_last('.cx')
		// Seed the bundled tier: frozen modules MAY compose other frozen
		// modules by [?lib] (cx-stdlib/supervise imports sched/time/fp —
		// SUP-1, #765), so resolution runs against the bundled table.
		mut table := code.new_module_table()
		code.register_bundled_stdlib(mut table)
		mod := code.load_module(src, mod_name, mut table) or {
			assert false, 'load_module(${mod_name}): ${err}'
			continue
		}
		for def_name, def in mod.defs {
			if def.purity != cx.Purity.impure_ {
				continue
			}
			checked++
			body := cx.parse_program(def.body) or {
				assert false, '${mod_name}:${def_name} body parse: ${err}'
				continue
			}
			if !code.node_calls_impure_builtin(body.body) {
				unclassified << '${mod_name}:${def_name}'
			}
		}
	}
	assert checked > 0, 'no impure stdlib defs seen — the gate must not pass vacuously'
	// #818 CLOSED the exception table: every impure-declared stdlib def now
	// reaches a callee the engine classifies impure, so the invariant is
	// enforced with NO backlog. A new impure def in any pack fails here
	// until it is classified — there is no longer a list to add it to.
	assert unclassified.len == 0, 'these stdlib defs DECLARE impure but reach no callee the engine classifies impure — ' +
		'a pure-required context (a fold reducer, a pure [?def]) would admit them instead of refusing loud (#788). ' +
		'Classify the verb: ring2_impure_register for a Ring-2 pack; for a Ring-1 pack either capability_gated_prims() ' +
		'(if it crosses a gated effect point — the direction-1 fold then marks it impure) or builtin_purity_table() ' +
		'PLUS a reason in impure_without_capability_exceptions() (#818): ${unclassified.join(', ')}'
}

// ── #792 (batch #796): data-AST source positions ───────────────────────
// POST-APPLY umbrella addition — not in
// scripts/consolidation/eval_semantics.files; reconcile it into the
// manifest inputs before any future regeneration.
//
// Every schema-validation diagnostic printed `FILE:0:0`: the DATA AST
// carried no source positions for the validator to report (the PROGRAM
// AST has `pos`; the data reading did not). parse_cx_positioned now
// records an element's position on its ElementMeta, and the validator
// stamps each diagnostic with the position of the element it is about.
const w792_schema = '[schema of=order]

[order
  [attr id::string [req]]
  [elem item [card "1..*"]]
]

[item
  [attr sku::string [req]]
]
'

// The middle item is missing its required sku=, so S002 must point at
// LINE 3 — not at the document, not at the first item, and not at 0:0.
const w792_doc = "[order id='o-1'
  [item sku='A']
  [item]
  [item sku='C']]
"

fn test_schema_diagnostics_report_source_positions() {
	res := cx.parse_cx_positioned(w792_doc) or {
		assert false, 'parse: ${err}'
		return
	}
	doc := res.single or {
		assert false, 'expected a single document'
		return
	}
	rep := cx.validate(doc, w792_schema) or {
		assert false, 'validate: ${err}'
		return
	}
	mut s002 := []cx.Diagnostic{}
	for d in rep.diagnostics {
		if d.code == 'S002' {
			s002 << d
		}
	}
	assert s002.len == 1, 'expected exactly one S002, got ${rep.diagnostics.map(it.code)}'
	assert s002[0].line == 3, 'S002 must point at the offending item on line 3, got line ${s002[0].line}'
	assert s002[0].col > 0, 'a reported position must carry a 1-based column, got ${s002[0].col}'
	// The rendered CLI form is the surface the issue reported as FILE:0:0.
	rendered := rep.render('order.cxd')
	assert rendered.contains('order.cxd:3:'), 'the rendered diagnostic must carry the real position, got: ${rendered}'
	assert !rendered.contains(':0:0:'), 'no diagnostic may still report 0:0, got: ${rendered}'
}

// Positions are PRESENTATION — the anchor/comment standing. The same
// source read with and without tracking must produce identical canonical
// bytes and an identical Tier-1 address; if either moved, positions would
// have leaked into identity.
fn test_positions_are_inert_to_canonical_bytes_and_identity() {
	plain := cx.parse_cx(w792_doc) or {
		assert false, 'parse: ${err}'
		return
	}
	positioned := cx.parse_cx_positioned(w792_doc) or {
		assert false, 'parse positioned: ${err}'
		return
	}
	pdoc := plain.single or { return }
	qdoc := positioned.single or { return }
	assert cx.emit_cx(pdoc) == cx.emit_cx(qdoc), 'positions moved the CANONICAL BYTES — they must be inert'
	assert pdoc.elements.len == 1 && qdoc.elements.len == 1, 'expected one root element'
	pa := code.render_canonical(code.value_tier1_address(pdoc.elements[0]))
	qa := code.render_canonical(code.value_tier1_address(qdoc.elements[0]))
	assert pa == qa, 'positions moved the TIER-1 ADDRESS — a moved address is a defect:\n plain: ${pa}\n  pos.: ${qa}'
}

// Tracking is opt-in so the ordinary parse allocates no ElementMeta it
// did not already need (meta is lazily allocated; stamping every element
// would add one allocation per element to every parse in the system).
fn test_ordinary_parse_records_no_positions() {
	plain := cx.parse_cx(w792_doc) or {
		assert false, 'parse: ${err}'
		return
	}
	doc := plain.single or { return }
	root := doc.elements[0]
	assert root is cx.Element, 'expected an element root'
	e := root as cx.Element
	assert e.pos() == none, 'an ordinary parse must record NO positions (opt-in — meta stays unallocated)'
	positioned := cx.parse_cx_positioned(w792_doc) or { return }
	qdoc := positioned.single or { return }
	q := qdoc.elements[0] as cx.Element
	assert q.pos() != none, 'the positioned door must record positions'
}

// ── #780: module-loaded defs carry their DECLARED purity ────────────────
// POST-APPLY umbrella addition — not in
// scripts/consolidation/eval_semantics.files; reconcile it into the
// manifest inputs before any future regeneration.
//
// The module loader's scope construction built each def's Closure
// without setting declared_impure, which only eval_def (the
// PROGRAM-level registration site) set. Consumers of the flag therefore
// saw every module-defined def as undeclared, and validate.md §3.6's
// purity gate — an impure `validate-with=` validator is a malformed
// schema (CXER1603) — refused a program-level impure validator while
// ADMITTING the identical module-defined one. Two registration sites,
// two trust postures.
//
// The fixture the issue asks for: the two spellings PAIRED, both
// required to refuse. The third case is the guard against over-refusing
// — a module-defined PURE validator must still run.
const w780_impure_mod = "[?def loud-check scope=public impure [returns bool] (\$v::int)\n  true]\n"
const w780_pure_mod = "[?def quiet-check scope=public pure [returns bool] (\$v::int)\n  true]\n"

fn w780_run(dir string, name string, src string) string {
	os.write_file(os.join_path(dir, name), src) or { panic('write ${name}: ${err}') }
	res := os.execute('cd ${dir} && ${cx_binary()} ${name}')
	return res.output
}

fn test_module_defined_impure_validator_refuses_like_program_level() {
	dir := os.join_path(os.temp_dir(), 'cx_w780_${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or {
		assert false, 'mkdir ${dir}: ${err}'
		return
	}
	defer {
		os.rmdir_all(dir) or {}
	}
	os.write_file(os.join_path(dir, 'helpers.cx'), w780_impure_mod + w780_pure_mod) or {
		assert false, 'write helpers: ${err}'
		return
	}
	// (a) the MODULE-defined impure validator — the defect: this used to
	// return [ok …] while (b) refused.
	mod_out := w780_run(dir, 'mod.cx', "[?lib 'cx-stdlib/validate']
[?lib './helpers.cx' :as h]
[\$validate:validate-shape
  [rec [score 4]]
  [schema [field name=\"score\" type=\"int\" validate-with=h:loud-check]]]
")
	assert mod_out.contains('CXER1603'), 'a MODULE-defined impure validator must refuse like the program-level one, got: ${mod_out}'
	// (b) the program-level twin (already pinned by validate-023) — asserted
	// here too so the pair is checked in one place.
	prog_out := w780_run(dir, 'prog.cx', "[?lib 'cx-stdlib/validate']
[?def loud-check impure [returns bool] (\$v::int)
  true]
[\$validate:validate-shape
  [rec [score 4]]
  [schema [field name=\"score\" type=\"int\" validate-with=loud-check]]]
")
	assert prog_out.contains('CXER1603'), 'the program-level impure validator must refuse, got: ${prog_out}'
	// (c) the guard against over-refusing: a module-defined PURE validator
	// still runs. Without this the fix could pass by refusing everything.
	pure_out := w780_run(dir, 'pure.cx', "[?lib 'cx-stdlib/validate']
[?lib './helpers.cx' :as h]
[\$validate:validate-shape
  [rec [score 4]]
  [schema [field name=\"score\" type=\"int\" validate-with=h:quiet-check]]]
")
	assert !pure_out.contains('CXER1603'), 'a module-defined PURE validator must still be admitted, got: ${pure_out}'
	assert pure_out.contains('ok'), 'the pure validator must validate the record, got: ${pure_out}'
}

// ── #771: eval_code renders relations WHOLE — API/CLI parity ───────────
// POST-APPLY umbrella addition — not in
// scripts/consolidation/eval_semantics.files; reconcile it into the
// manifest inputs before any future regeneration.
//
// eval_code returned only a lazy comprehension's FIRST item (a two-group
// [group-by] relation rendered as its first group — which is how it
// surfaced: a quoted-query pipeline appeared to LOSE a group), while the
// CLI printed all of it. The render path rendered an iterator by its head
// instead of materializing.
//
// The fix was live but UNPINNED, and its failure mode is silent — a
// truncated relation looks like a smaller answer, not an error. This is
// the parity pin the issue asks for: the API and the CLI must agree on
// the SAME program, so neither can drift alone.
//
// SCOPE, stated honestly: this pins the CONTRACT (nothing truncated;
// API == CLI), not one mechanism. Disarming the EV-PULL force at the
// single-form result boundary (force_lazy_result, api.v) does NOT
// regress these shapes — verified by doing it — because neither a
// literal-sequence comprehension nor a [group-by] relation still
// reaches that boundary as an unforced IteratorNode. So the force is
// not what these cases exercise, and a future change that reintroduces
// laziness upstream would need its own repro to be caught here. Kept
// because the user-visible contract is what the issue is about and what
// silently broke.
const w771_programs = [
	'[?for [in $x (1, 2, 3)] [yield $x]]',
	'[?let [= $r [?for [in $x (1, 2, 3)] [yield $x]]] $r]',
]

fn test_eval_code_matches_cli_on_comprehension_results() {
	dir := os.join_path(os.temp_dir(), 'cx_w771_${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or {
		assert false, 'mkdir ${dir}: ${err}'
		return
	}
	defer {
		os.rmdir_all(dir) or {}
	}
	for i, prog in w771_programs {
		api := code.eval_code('[empty]', prog, 'cx') or {
			assert false, 'eval_code failed on `${prog}`: ${err}'
			continue
		}
		// Every item must survive the API boundary — the defect dropped
		// all but the first.
		for want in ['1', '2', '3'] {
			assert api.contains(want), 'eval_code TRUNCATED the relation (#771) — `${want}` missing from `${api.replace('\n',
				' | ')}` for: ${prog}'
		}
		// …and the API must agree with the CLI on the same program, which
		// is the invariant that keeps either side from drifting alone.
		f := os.join_path(dir, 'p${i}.cx')
		os.write_file(f, prog + '\n') or {
			assert false, 'write: ${err}'
			continue
		}
		res := os.execute('${cx_binary()} ${f}')
		cli_items := res.output.split('\n').map(it.trim_space()).filter(it != '')
		api_items := api.split('\n').map(it.trim_space()).filter(it != '')
		assert api_items == cli_items, 'API/CLI divergence on `${prog}`:\n  eval_code=${api_items}\n  cli      =${cli_items}'
	}
}

// ── #821: the streaming mode a caller is TOLD == the path taken ────────
// POST-APPLY umbrella addition — not in
// scripts/consolidation/eval_semantics.files; reconcile it into the
// manifest inputs before any future regeneration.
//
// eval_code_streaming silently falls back to full materialisation for
// every shape it cannot stream. Output stays correct, so the failure is
// invisible: a caller streaming a large input to bound memory does not
// get that bound and cannot tell, because a genuinely streamed small
// result is also a single chunk.
//
// eval_code_streamable lets the caller ask first. The risk in adding a
// predicate is that it becomes a SECOND spelling of the condition and
// drifts from the dispatch — exactly what happened between the two def
// registration sites (#780). Structurally they now share
// stream_mode_of; this test is the behavioural backstop, asserting the
// predicate against the OBSERVED chunk behaviour rather than against a
// restatement of the rule.
struct W821Case {
	prog     string
	target   string
	streams  bool
	why      string
}

const w821_cases = [
	W821Case{'[?for [in $x (1, 2, 3)] [yield $x]]', 'text', true, 'bare comprehension, text target'},
	W821Case{'[?for [in $x (1, 2, 3)] [yield $x]]', 'cx', true, 'bare comprehension, cx target'},
	// Condition 1 — a non-text/cx target never streams.
	W821Case{'[?for [in $x (1, 2, 3)] [yield $x]]', 'json', false, 'json target'},
	// Condition 3 — order-by/group-by must see the whole set first, so
	// they can NEVER stream. Inherent, not a gap.
	W821Case{'[?for [in $x (3, 1, 2)] [order-by $x] [yield $x]]', 'text', false, 'order-by'},
	// Condition 2 — not a comprehension at all.
	W821Case{'[$count (1, 2, 3)]', 'text', false, 'plain call'},
	W821Case{'(1, 2, 3)', 'text', false, 'literal'},
	// A program that does not parse reports buffered (the streaming call
	// surfaces the parse error on the one-shot path).
	W821Case{'[?for [in $x', 'text', false, 'unparseable'},
]

fn test_streamable_predicate_matches_the_path_taken() {
	for c in w821_cases {
		assert code.eval_code_streamable(c.prog, c.target) == c.streams,
			'eval_code_streamable disagrees for ${c.why}: expected ${c.streams} — ${c.prog}'
	}
}

// The backstop: drive the real streaming call and count chunks. A
// streamed run over enough items MUST produce more than one chunk in
// unbuffered mode; a buffered run produces exactly one however many
// items it yields. This catches the predicate drifting from the
// dispatch even if both are edited together.
fn test_streamable_predicate_agrees_with_observed_chunking() {
	// 400 items — comfortably more than one flush in unbuffered mode.
	streaming_prog := '[?for [in $x [\$range 1 400]] [yield \$x]]'
	buffering_prog := '[?for [in $x [\$range 1 400]] [order-by \$x] [yield \$x]]'
	for prog in [streaming_prog, buffering_prog] {
		// Count through a POINTER: a closure captures by value, so a
		// plain `int` would read back 0 however many times the sink
		// fired (which is exactly how the first draft of this test
		// fooled itself).
		mut n := 0
		p := &n
		code.eval_code_streaming_opts('[empty]', prog, 'text', fn [p] (s string) ! {
			unsafe {
				*p = *p + 1
			}
		}, true) or {
			assert false, 'streaming call failed for ${prog}: ${err}'
			continue
		}
		chunks := n
		predicted := code.eval_code_streamable(prog, 'text')
		observed_multi := chunks > 1
		assert predicted == observed_multi,
			'predicate says streams=${predicted} but the call produced ${chunks} chunk(s): ${prog}'
	}
}

// ── #822: the CLI streams, and its bytes do not move ───────────────────
// POST-APPLY umbrella addition — not in
// scripts/consolidation/eval_semantics.files; reconcile it into the
// manifest inputs before any future regeneration.
//
// Every CLI eval used to build the whole rendered output as one string
// before printing it: measured 514 MiB peak RSS on the 10 MB bench
// fixture, growing at ~45x the input size. It now routes through
// eval_code_streaming with a stdout sink (199 MiB on the same fixture,
// ~11x marginal).
//
// The regression risk is not the memory — it is the BYTES. Streaming
// renders through a different code path (per-yield chunks vs one render
// of the whole result), so this pins the contract that matters: the CLI
// emits exactly what the one-shot API returns, for shapes that stream
// AND for shapes that fall back.
const w822_doc = '[services
  [service id=1 name=svc-1 [tags a b]]
  [service id=2 name=svc-2 [tags c]]
  [service id=3 name=svc-3 [tags d e f]]]'

struct W822Case {
	prog   string
	target string
}

const w822_cases = [
	// streaming-eligible
	W822Case{'[?for [in $s $doc/service] [yield $s]]', 'text'},
	W822Case{'[?for [in $s $doc/service] [yield $s/@id]]', 'cx'},
	// falls back: order-by cannot stream (needs the whole set first)
	W822Case{'[?for [in $s $doc/service] [order-by $s/@id] [yield $s/@id]]', 'text'},
	// falls back: not a comprehension
	W822Case{'[$count $doc/service]', 'text'},
	// falls back: non-streaming target
	W822Case{'[?for [in $s $doc/service] [yield $s/@id]]', 'json'},
]

fn test_cli_output_matches_one_shot_api_after_streaming() {
	dir := os.join_path(os.temp_dir(), 'cx_w822_${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or {
		assert false, 'mkdir: ${err}'
		return
	}
	defer {
		os.rmdir_all(dir) or {}
	}
	data := os.join_path(dir, 'doc.cx')
	os.write_file(data, w822_doc + '\n') or {
		assert false, 'write: ${err}'
		return
	}
	mut streamed := 0
	for c in w822_cases {
		api := code.eval_code(w822_doc, c.prog, c.target) or {
			assert false, 'eval_code failed for `${c.prog}` @ ${c.target}: ${err}'
			continue
		}
		// PYE-2 (#926): flags bind BEFORE the -e resource — tokens after
		// `-e EXPR` are the program's argv.
		res := os.execute('${cx_binary()} eval --data=${data} --target=${c.target} -e ${os.quoted_path(c.prog)}')
		assert res.exit_code == 0, 'cx eval exited ${res.exit_code} for `${c.prog}`: ${res.output}'
		assert res.output == api, 'CLI output diverged from the one-shot API after the streaming cutover (#822)\n' +
			'  program: ${c.prog}\n  target : ${c.target}\n  api    : ${api.len} bytes\n  cli    : ${res.output.len} bytes'
		if code.eval_code_streamable(c.prog, c.target) {
			streamed++
		}
	}
	// The matrix must actually exercise BOTH paths, or it would pass
	// while proving only one of them.
	assert streamed > 0, 'no streaming-eligible case in the matrix'
	assert streamed < w822_cases.len, 'no fallback case in the matrix'
}

// eval_code_streaming must honour its OWN byte-equivalence contract for
// a resource that is valid DATA but not a valid PROGRAM (#822). It used
// to parse the program up front and return CXER0100, never reaching the
// one-shot path that owns the §1.3 data-fallback ("a pure-data resource
// evaluates to itself") — so eval_code returned the data reading while
// eval_code_streaming errored on the same input. It also contradicted
// eval_code_stream_mode, which already reported `.buffered` for an
// unparseable program.
//
// Found by routing the CLI through the streaming call: every prose
// document depends on that fallback.
fn test_streaming_honours_the_data_fallback_like_one_shot() {
	prose := '[note — "use [?let] for bindings"]'
	oneshot := code.eval_code('', prose, 'text') or {
		assert false, 'eval_code must fall back to the data reading: ${err}'
		return
	}
	mut got := ''
	p := &got
	code.eval_code_streaming('', prose, 'text', fn [p] (chunk string) ! {
		unsafe {
			*p = *p + chunk
		}
	}) or {
		assert false, 'eval_code_streaming must fall back too, not error: ${err}'
		return
	}
	assert got == oneshot, 'streaming diverged from one-shot on a data-fallback resource:\n  one-shot: ${oneshot}\n  streamed: ${got}'
	assert got.contains('use [?let] for bindings'), 'content lost: ${got}'
	// The predicate already said "buffered" for this input — the dispatch
	// now agrees instead of erroring.
	assert !code.eval_code_streamable(prose, 'text'), 'an unparseable program must report buffered'
}

// eval_code_streaming's CENTRAL contract: concatenating every chunk
// reproduces eval_code's bytes exactly. That is the whole basis on
// which a caller may swap one surface for the other, and it had no
// general test — gate 15 drives a [?for] comprehension, which renders
// newline-separated on BOTH paths, so the shapes that actually diverge
// were never exercised.
//
// Two real violations were found by routing the CLI through this call
// (#822) and are covered here: a data-fallback resource (streaming used
// to error where one-shot returned the data reading) and [?map] (whose
// streamed path emitted [?for]-style items instead of a sequence
// literal — fixed in #823, and the map rows below now exercise the
// STREAMED path rather than the exclusion).
const w823_equivalence_programs = [
	// streams
	'[?for [in $x (1, 2, 3, 4)] [yield $x]]',
	'[?for [in $x (1, 2, 3, 4)] [where [> $x 1]] [yield $x]]',
	// buffered: order-by / group-by must see the whole set
	'[?for [in $x (3, 1, 2)] [order-by $x] [yield $x]]',
	// buffered: [par] — the streamed path has no parallel branch (#822)
	'[?for [in $x (1, 2, 3, 4)] [yield $x] [par 2]]',
	// STREAMED (#823): a [?map] result renders as a sequence literal, and
	// the streaming renderer now writes that container itself. Every
	// [par] / [ordered] / width form is here because the acceptance is
	// byte-equivalence ACROSS them — the parallel arm emits through a
	// completion frontier, so it is a different emission order arriving at
	// the same bytes.
	'[?map (1, 2, 3, 4) [using [?fn $x [* $x $x]]]]',
	'[?map (1, 2, 3, 4) [using [?fn $x [* $x $x]]] [par]]',
	'[?map (1, 2, 3, 4) [using [?fn $x [* $x $x]]] [par] [ordered]]',
	'[?map (1, 2, 3, 4) [using [?fn $x [* $x $x]]] [par 2]]',
	'[?map (1, 2, 3, 4) [using [?fn $x [* $x $x]]] [par 2] [ordered]]',
	// the degenerate cardinalities the sequence wrapper has to get right:
	// an empty map renders `()`, a single item renders `(x)` with no
	// separator — both were unreachable while the shape was excluded.
	'[?map () [using [?fn $x [* $x $x]]]]',
	'[?map (7) [using [?fn $x [* $x $x]]]]',
	// element-valued items exercise the collection-item renderer rather
	// than the scalar one.
	'[?map (1, 2) [using [?fn $x [item :n $x]]]]',
	// buffered: not a comprehension at all
	'[$count (1, 2, 3)]',
	'(1, 2, 3)',
]

fn test_streaming_concat_equals_one_shot_across_shapes() {
	for target in ['text', 'cx'] {
		for prog in w823_equivalence_programs {
			oneshot := code.eval_code('', prog, target) or {
				assert false, 'eval_code failed for `${prog}` @ ${target}: ${err}'
				continue
			}
			mut got := ''
			p := &got
			code.eval_code_streaming('', prog, target, fn [p] (chunk string) ! {
				unsafe {
					*p = *p + chunk
				}
			}) or {
				assert false, 'eval_code_streaming failed for `${prog}` @ ${target}: ${err}'
				continue
			}
			// Liveness before agreement (#851): two paths that both produce
			// nothing agree perfectly and prove nothing. Every program in
			// this list emits — `[?map () …]` renders `()`, not "" — so this
			// costs nothing today and stops a future addition from joining
			// the vacuous class silently.
			assert oneshot.len > 0,
				'VACUOUS PARITY: `${prog}` @ ${target} produced NO output on the one-shot ' +
				'path, so comparing the two paths proves nothing (#851)'
			assert got == oneshot, 'streaming/one-shot BYTE DIVERGENCE (the contract this surface rests on)\n' +
				'  program : ${prog}\n  target  : ${target}\n  one-shot: ${oneshot}\n  streamed: ${got}'
		}
	}
}

// §10.5.1 EV-ASYNC-SPAWN, the completion half: "a spawned body that is
// never awaited still runs to a terminal state BEFORE TOP-LEVEL PROGRAM
// RETURN … `[?async [ship $order]]` with no await MUST still ship the
// order."
//
// It did not. An un-awaited future was abandoned when the top level
// returned: this exact program returned in ~106 ms with its 800 ms body
// dropped on the floor. Spawning was eager — the body STARTS without an
// await (#541) — but starting is not the guarantee. Found working #814,
// whose fixture had been reaching for this guarantee through a scheduling
// race and could only ever measure luck.
//
// The observable is ELAPSED TIME AT THE CALLER, which is what makes this
// deterministic where the conformance case could not be. A conformance
// case compares a program's value, and the guarantee is about what must
// be true by the time that value exists — unobservable from inside. Here
// the assertion is a LOWER bound on the caller's wall clock, so machine
// load can only ever push it further into the passing side. That is the
// opposite of the load sensitivity #814 filed: no compile storm can make
// a dropped body look completed.
fn test_fire_and_forget_completes_before_top_level_return() {
	body_ms := 800
	prog := '[?let [= \$f [?async [?let [= \$s [?sleep ${body_ms}ms]] [?test-counter name=ff op=inc]]]] [spawned]]'
	t0 := time.now()
	out := code.eval_code('', prog, 'text') or {
		assert false, 'eval_code failed: ${err}'
		return
	}
	elapsed := time.since(t0).milliseconds()
	assert out.trim_space() == '[spawned]', 'unexpected program value: ${out}'
	// Generous margin under the body's own duration — the claim is that
	// the call did not return while an 800 ms body was still running, not
	// that it took any particular time.
	assert elapsed >= i64(body_ms) - 100,
		'a fire-and-forget body was ABANDONED at top-level return (§10.5.1): ' +
		'the call returned in ${elapsed} ms with an ${body_ms} ms body still running'
}

// The mock-clock companion. A fire-and-forget body parked at
// `[?sleep DUR mock]` waits on LOGICAL time, which only an await barrier
// moves — and by definition nothing is awaiting it. The exit drain has to
// be that barrier, or the completion guarantee above turns a mock sleep
// into a hang. Real time never reaches a logical deadline, so this
// returning at all IS the assertion.
fn test_fire_and_forget_mock_sleep_does_not_hang_exit() {
	prog := '[?let [= \$f [?async [?let [= \$s [?sleep 5s mock]] [?test-counter name=mk op=inc]]]] [spawned]]'
	t0 := time.now()
	out := code.eval_code('', prog, 'text') or {
		assert false, 'eval_code failed: ${err}'
		return
	}
	elapsed := time.since(t0).milliseconds()
	assert out.trim_space() == '[spawned]', 'unexpected program value: ${out}'
	assert elapsed < 5000,
		'the exit drain waited on LOGICAL time in real seconds (${elapsed} ms) — ' +
		'it must advance the mock clock the way the await barrier does'
}

// The equivalence rows above pass VACUOUSLY for any shape that quietly
// buffers — a fallback to the one-shot path trivially reproduces the
// one-shot bytes. #823's acceptance is that [?map] STREAMS again, so the
// engagement is asserted separately against the same authority callers
// read (stream_mode_of, via eval_code_streamable).
fn test_map_shapes_actually_stream_not_silently_buffer() {
	map_programs := w823_equivalence_programs.filter(it.starts_with('[?map'))
	assert map_programs.len >= 8, 'the [?map] equivalence rows went missing'
	for target in ['text', 'cx'] {
		for prog in map_programs {
			assert code.eval_code_streamable(prog, target),
				'[?map] must stream, not buffer (#823): ${prog} @ ${target}'
		}
	}
}

// ── §6.5.0 directive-purity mirror (RULED tables-1a, #756) ─────────────
//
// POST-APPLY umbrella addition — not in
// scripts/consolidation/eval_semantics.files; reconcile it into the
// manifest inputs before any future regeneration.
//
// code.md §6.5.0 is the normative closed directive-purity table;
// purity_checker.v is its mirror. This gate asserts equality in BOTH
// directions, so the classification cannot drift from the vocabulary
// again — which is exactly how it got to 56 classified heads against 85
// dispatched, with 13 rows naming directives the engine answers "unknown
// directive" for (#756).
//
// The parse is deliberately structural (the §6.5.0 table rows), not a
// keyword scan: a gate that greps for prose passes when the prose moves.

fn spec_directive_purity_rows() map[string]string {
	path := os.real_path(os.join_path(os.dir(@FILE), '..', '..',
		'spec', '03-approved', 'core', 'code.md'))
	body := os.read_file(path) or {
		assert false, 'read code.md: ${err}'
		return map[string]string{}
	}
	start := body.index('### §6.5.0') or {
		assert false, 'code.md has no §6.5.0 directive-purity section'
		return map[string]string{}
	}
	rest := body[start..]
	stop := rest.index('### §6.5.1') or { rest.len }
	mut out := map[string]string{}
	for line in rest[..stop].split_into_lines() {
		if !line.starts_with('| `[?') {
			continue
		}
		cells := line.split('|')
		if cells.len < 3 {
			continue
		}
		head := cells[1].trim_space().trim('`').trim_space()
		cls := cells[2].trim_space()
		if head.len == 0 || cls.len == 0 {
			continue
		}
		out[head.trim('[]')] = cls
	}
	return out
}

fn test_directive_purity_mirrors_the_spec_table() {
	spec := spec_directive_purity_rows()
	assert spec.len > 50, 'parsed ${spec.len} rows from code.md §6.5.0 — the gate has nothing to enforce'
	impl_map := code.directive_purity_mirror()
	diagnostics := code.directive_purity_diagnostics_only()

	// direction A: every spec row is classified identically in the mirror.
	mut missing := []string{}
	mut disagree := []string{}
	for head, cls in spec {
		impl_cls := impl_map[head] or {
			missing << head
			continue
		}
		if impl_cls != cls {
			disagree << '${head}: spec says `${cls}`, implementation says `${impl_cls}`'
		}
	}
	assert missing.len == 0, 'code.md §6.5.0 classifies these but purity_checker.v does not — ' +
		'the mirror lags the spec: ${missing.join(', ')}'
	assert disagree.len == 0, 'spec ↔ implementation purity disagreement:\n  ' + disagree.join('\n  ')

	// direction B: every classified head has a spec row, EXCEPT the
	// test-only diagnostics, which §6.5.0 deliberately does not carry.
	mut unspecified := []string{}
	for head, _ in impl_map {
		if head in spec || head in diagnostics {
			continue
		}
		unspecified << head
	}
	assert unspecified.len == 0, 'purity_checker.v classifies these but code.md §6.5.0 has no row — ' +
		'the table is normative and closed, so the row lands in the spec first (RULED tables-1a): ' +
		unspecified.join(', ')
}

fn test_directive_purity_covers_the_live_vocabulary() {
	// The defect this issue was filed for: the classification lagged the
	// DISPATCH, so an unclassified head shielded the def that used it. Every
	// head the engine actually answers must be classified.
	spec := spec_directive_purity_rows()
	impl_map := code.directive_purity_mirror()
	assert spec.len > 0 && impl_map.len >= spec.len
	// The registry is the vocabulary of record; §6.5.0 must cover all of it.
	path := os.real_path(os.join_path(os.dir(@FILE), '..', '..',
		'spec', '03-approved', 'core', 'code.md'))
	body := os.read_file(path) or {
		assert false, 'read code.md: ${err}'
		return
	}
	mut registered := []string{}
	for line in body.split_into_lines() {
		if !line.starts_with('| `[?') {
			continue
		}
		head := line.split('|')[1].trim_space().trim('`').trim_space().trim('[]')
		if head.contains(' ') || head in registered {
			continue
		}
		registered << head
	}
	mut unclassified := []string{}
	for head in registered {
		if head !in spec {
			unclassified << head
		}
	}
	assert unclassified.len == 0, 'these §4.1-registered directives carry no §6.5.0 purity row — ' +
		'an unclassified head is exactly the shield #756 closed: ${unclassified.join(', ')}'
}
